def _script(bytecode: bytes) -> bytes:
    data = bytearray(0x84 + 0x40)
    struct.pack_into("<I", data, 0x80, 1)
    data.extend(bytecode)
    return bytes(data)


def _menu_archive_entry(data: bytes, index: int) -> bytes:
    count = struct.unpack_from("<I", data, 0)[0]
    offsets = struct.unpack_from(f"<{count}I", data, 4)
    start = offsets[index]
    end = offsets[index + 1] if index + 1 < count else len(data)
    return data[start:end]


def _decoded_menu_archive_entry(
    data: bytes,
    index: int,
    expected_size: int,
) -> bytes:
    entry = _menu_archive_entry(data, index)
    return decompress_lzss(entry + bytes(16), expected_size).data


def _shop_group(
    data: bytes,
    *,
    record: int,
    record_size: int,
    group_offset: int,
    capacity: int,
) -> tuple[int, ...]:
    start = record * record_size + group_offset
    return tuple(value for value in data[start : start + capacity] if value)


def _prepared_field(target: int, bytecode: bytes) -> PreparedReplacement:
    components = [b""] * 9
    components[5] = _script(bytecode)
    return PreparedReplacement(
        f"synthetic field {target}",
        target,
        Path("."),
        target,
        b"",
        tuple(components),
    )


def _prepared_route() -> tuple[PreparedReplacement, ...]:
    successors = {field: [] for field in ROUTE}
    for source, destination in ROUTE_EDGES:
        successors[source].append(destination)

    prepared: list[PreparedReplacement] = []
    for field in ROUTE:
        spec = next(spec for spec in CLONES if spec.target_field == field)
        custom_destinations = {
            edit.new_field for edit in spec.preserved_custom_transitions
        }
        fixed_transitions = b"".join(
            (
                _change_field(destination, 1)
                if (field, destination) == (728, 726)
                else _change_field(destination)
            )
            for destination in successors[field]
            if destination not in custom_destinations
        )
        if field == 384:
            fixed_transitions += _change_field(384, 0)
        bytecode = bytearray(fixed_transitions + b"\x00")
        custom_end = max(
            (
                edit.pc
                + len(
                    _custom_field_transition(
                        edit.new_field,
                        edit.new_parameter,
                        edit.old_mode,
                        edit.old_fade,
                    )
                )
                for edit in spec.preserved_custom_transitions
            ),
            default=0,
        )
        bytecode.extend(b"\x14" * max(0, custom_end - len(bytecode)))
        for edit in spec.preserved_custom_transitions:
            encoded = _custom_field_transition(
                edit.new_field,
                edit.new_parameter,
                edit.old_mode,
                edit.old_fade,
            )
            bytecode[edit.pc : edit.pc + len(encoded)] = encoded
        if field == ROUTE[-1]:
            bytecode.extend(_worldmap(21, 1) + b"\x5B")
        prepared.append(_prepared_field(field, bytes(bytecode)))
    return tuple(prepared)


def _clone(target_field: int):
    return next(spec for spec in CLONES if spec.target_field == target_field)


def _donor_and_transformed(target_field: int) -> tuple[AtelScript, AtelScript]:
    project = REPOSITORY_ROOT
    spec = _clone(target_field)
    source = (
        project / "work" / spec.bundle_directory / "05_scripts.bin"
    ).read_bytes()
    transformed, _ = _transform_clone_script(spec, source)
    return AtelScript(source), AtelScript(transformed)


def _prepared_transformed_route() -> tuple[PreparedReplacement, ...]:
    project = REPOSITORY_ROOT
    prepared: list[PreparedReplacement] = []
    for spec in CLONES:
        source = (
            project / "work" / spec.bundle_directory / "05_scripts.bin"
        ).read_bytes()
        transformed, _ = _transform_clone_script(spec, source)
        components = [b""] * 9
        if spec.target_field == 728:
            components[1] = (
                project / "work" / spec.bundle_directory / "01_walkmesh.bin"
            ).read_bytes()
        components[5] = transformed
        prepared.append(
            PreparedReplacement(
                spec.role,
                spec.target_field,
                project / "work" / spec.bundle_directory,
                spec.target_bundle_id,
                b"",
                tuple(components),
            )
        )
    return tuple(prepared)


