class DungeonRouteTests(unittest.TestCase):
    def test_route_is_the_complete_standalone_debug_chain(self) -> None:
        self.assertEqual(
            ROUTE,
            (
                729,
                364,
                360,
                720,
                721,
                363,
                362,
                727,
                372,
                361,
                722,
                723,
                375,
                387,
                725,
                726,
                366,
                367,
                385,
                386,
                368,
                369,
                370,
                371,
                724,
                376,
                384,
                377,
                378,
                379,
                382,
                383,
                728,
            ),
        )
        self.assertEqual(len(ROUTE), 33)
        self.assertEqual(len(ROUTE_EDGES), 66)
        self.assertEqual(validate_route(), ROUTE_EDGES)
        self.assertEqual(tuple(spec.target_field for spec in CLONES), ROUTE)
        self.assertLessEqual(set(ROUTE), SAFE_ROUTE_TARGETS)
        self.assertNotIn(617, ROUTE)
        self.assertNotIn(618, ROUTE)
        self.assertNotIn(670, ROUTE)
        self.assertLessEqual({385, 386}, set(ROUTE))
        self.assertEqual(ROUTE[-2:], (383, 728))
        self.assertNotIn(388, ROUTE)
        self.assertNotIn(507, ROUTE)
        self.assertEqual(len({spec.target_bundle_id for spec in CLONES}), len(CLONES))
        self.assertEqual(len({spec.target_graphics_id for spec in CLONES}), len(CLONES))

    def test_arrival_contracts_cover_every_directed_link_and_world_entry(
        self,
    ) -> None:
        world = tuple(
            contract
            for contract in ARRIVAL_CONTINUITY_CONTRACTS
            if contract.source_field is None
        )
        route = tuple(
            (contract.source_field, contract.destination_field)
            for contract in ARRIVAL_CONTINUITY_CONTRACTS
            if contract.source_field is not None
        )
        parameters = tuple(
            (contract.destination_field, contract.destination_parameter)
            for contract in ARRIVAL_CONTINUITY_CONTRACTS
        )

        self.assertEqual(
            tuple(
                (
                    contract.destination_field,
                    contract.destination_parameter,
                )
                for contract in world
            ),
            ((729, 0),),
        )
        self.assertEqual(route, ROUTE_EDGES)
        self.assertEqual(len(parameters), 67)
        self.assertEqual(len(set(parameters)), len(parameters))

    def test_every_active_entry_faces_forward_with_an_explicit_camera(
        self,
    ) -> None:
        prepared = {
            item.target_field: item
            for item in _prepared_transformed_route()
        }
        for contract in ARRIVAL_CONTINUITY_CONTRACTS:
            with self.subTest(
                source=contract.source_field,
                destination=contract.destination_field,
                parameter=contract.destination_parameter,
            ):
                actual = _read_field_entry(
                    prepared[contract.destination_field].components[5],
                    contract.destination_parameter,
                )
                self.assertEqual(
                    (
                        actual.x,
                        actual.z,
                        actual.walkmesh,
                        actual.camera_direction,
                        actual.actor_direction,
                    ),
                    (
                        contract.expected_entry.x,
                        contract.expected_entry.z,
                        contract.expected_entry.walkmesh,
                        contract.resolved_camera_direction,
                        contract.inward_direction,
                    ),
                )
                self.assertNotEqual(actual.camera_direction, 0xFF)
                self.assertNotEqual(actual.actor_direction, 0xFF)
                if contract.camera_direction is None:
                    self.assertEqual(
                        actual.camera_direction,
                        actual.actor_direction,
                    )

        # The lower-lift exit enters a genuinely curved tunnel and therefore
        # uses its southwest octant rather than a misleading due-west default.
        first_tunnel = _read_field_entry(prepared[360].components[5], 0)
        self.assertEqual(
            (first_tunnel.camera_direction, first_tunnel.actor_direction),
            (7, 7),
        )

        # The post-auxiliary stair lands just inside field 726's north wall.
        # A south-facing camera sits beyond that wall and produced the exact
        # white/black clipped frame captured in the v43 post-door save state.
        post_aux = _read_field_entry(prepared[726].components[5], 2)
        self.assertEqual(
            (post_aux.camera_direction, post_aux.actor_direction),
            (0, 4),
        )

        # The magnetic-conduit/save-point route enters at the west wall.
        # Camera octant 2 placed the eye outside that wall and reproduced the
        # clipped v44 frame; actor 2 remains inward while camera 6 stays inside.
        post_save_point = _read_field_entry(
            prepared[726].components[5],
            0,
        )
        self.assertEqual(
            (
                post_save_point.camera_direction,
                post_save_point.actor_direction,
            ),
            (6, 2),
        )

    def test_subway_return_arrival_clears_its_expanded_exit_volume(self) -> None:
        prepared = {
            item.target_field: item
            for item in _prepared_transformed_route()
        }
        contract = next(
            contract
            for contract in ARRIVAL_CONTINUITY_CONTRACTS
            if (
                contract.source_field,
                contract.destination_field,
                contract.destination_parameter,
            )
            == (363, 721, 1)
        )
        self.assertEqual(
            contract.expected_entry,
            FieldEntryAddition(-1250, -218, 0, 2, 2),
        )
        self.assertEqual(
            _read_field_entry(prepared[721].components[5], 1),
            contract.expected_entry,
        )

        editor = ScriptEditor(prepared[721].components[5])
        initializer = _pointed_script_body(
            editor,
            editor.get_script_pointer(13, 0),
        )
        self.assertEqual(initializer[:2], bytes.fromhex("BC 19"))
        self.assertEqual(initializer[15], 0x18)
        exit_x, exit_z = struct.unpack_from("<hh", initializer, 2)
        runtime_x_reach = initializer[16] * 2 + 16
        runtime_z_reach = initializer[17] * 2 + 16
        self.assertEqual(
            (exit_x, exit_z, runtime_x_reach, runtime_z_reach),
            (-1391, -211, 80, 336),
        )
        self.assertLessEqual(
            abs(contract.expected_entry.z - exit_z),
            runtime_z_reach,
        )
        self.assertGreaterEqual(
            abs(contract.expected_entry.x - exit_x) - runtime_x_reach,
            0x20,
        )
        # V92 used x=-1334, only 57 units from this 80-unit live reach.
        self.assertLess(abs(-1334 - exit_x) - runtime_x_reach, 0)

