    def test_scene_continuity_verifier_rejects_wrong_parameter_or_camera(
        self,
    ) -> None:
        prepared = list(_prepared_transformed_route())
        # This transition-focused fixture intentionally carries synthetic
        # walkmeshes; the field-507 route geometry has its own exact test.
        with patch.object(
            mass_driver,
            "_validate_final_party_arrival_walkmesh",
        ):
            verify_scene_continuity(prepared)

        source_index = next(
            index
            for index, item in enumerate(prepared)
            if item.target_field == 722
        )
        source = prepared[source_index]
        source_components = list(source.components)
        source_script = bytearray(source_components[5])
        source_parsed = ParsedAtelScript(bytes(source_script))
        pc = _clone(722).transitions[0].pc
        start = source_parsed.bytecode_offset + pc
        self.assertEqual(
            source_script[start : start + 5],
            _change_field(372, 3),
        )
        source_script[start : start + 5] = _change_field(372, 0)
        source_components[5] = bytes(source_script)
        wrong_parameter = prepared.copy()
        wrong_parameter[source_index] = replace(
            source,
            components=tuple(source_components),
        )
        with self.assertRaisesRegex(
            DungeonBuildError,
            "372/3 is not present|no checked transition",
        ):
            with patch.object(
                mass_driver,
                "_validate_final_party_arrival_walkmesh",
            ):
                verify_scene_continuity(wrong_parameter)

        destination_index = next(
            index
            for index, item in enumerate(prepared)
            if item.target_field == 372
        )
        destination = prepared[destination_index]
        destination_components = list(destination.components)
        destination_script = bytearray(destination_components[5])
        destination_parsed = ParsedAtelScript(bytes(destination_script))
        camera_offset = destination_parsed.bytecode_offset + 1 + 3 * 7 + 5
        self.assertEqual(destination_script[camera_offset], 6)
        destination_script[camera_offset] = 0xFF
        destination_components[5] = bytes(destination_script)
        inherited_camera = prepared.copy()
        inherited_camera[destination_index] = replace(
            destination,
            components=tuple(destination_components),
        )
        with self.assertRaisesRegex(
            DungeonBuildError,
            "Arrival 722->372/3",
        ):
            with patch.object(
                mass_driver,
                "_validate_final_party_arrival_walkmesh",
            ):
                verify_scene_continuity(inherited_camera)

