    def test_five_containment_vaults_use_full_width_automatic_boundaries(
        self,
    ) -> None:
        expected = {
            377: ((376, 1), (378, 0)),
            378: ((377, 1), (379, 0)),
            379: ((378, 1), (382, 0)),
            382: ((379, 1), (383, 0)),
            383: ((382, 1), (728, 0)),
        }
        for variant, (field, (south, north)) in enumerate(
            expected.items()
        ):
            with self.subTest(field=field):
                spec = _clone(field)
                gallery = spec.cloning_silo_gallery
                assert gallery is not None
                donor, transformed = _donor_and_transformed(field)
                prepared = _prepare_clone(
                    spec,
                    REPOSITORY_ROOT / "work",
                    REPOSITORY_ROOT
                    / "modules" / "mass_driver" / "content",
                )

                self.assertEqual(spec.source_field, 673)
                self.assertEqual(gallery.variant, variant)
                self.assertLess(len(prepared.bundle), 0x18000)
                self.assertEqual(
                    [part.data for part in parse_field(prepared.bundle).parts],
                    list(prepared.components),
                )
                assert prepared.header is not None
                self.assertEqual(
                    hashlib.sha256(prepared.header).hexdigest(),
                    ZEBOIM_STATION_FIELD_673_HEADER_SHA256,
                )
                self.assertEqual(
                    hashlib.sha256(prepared.components[MODEL_INDEX]).hexdigest(),
                    ZEBOIM_STATION_FIELD_673_MODELS_SHA256,
                )
                station_models = _indexed_bundle_entries(
                    prepared.components[MODEL_INDEX]
                )
                self.assertEqual(
                    hashlib.sha256(
                        station_models[ZEBOIM_STATION_TARGET_MODEL_INDEX]
                    ).hexdigest(),
                    ZEBOIM_STATION_RELOCATED_MODEL_SHA256,
                )
                self.assertEqual(
                    struct.unpack_from(
                        "<HhhhhhhH",
                        prepared.header,
                        0x190 + ZEBOIM_STATION_TARGET_NODE_INDEX * 16,
                    ),
                    (
                        ZEBOIM_STATION_NODE_FLAGS,
                        0,
                        ZEBOIM_STATION_Y_ROTATION,
                        0,
                        *ZEBOIM_STATION_PLACEMENT,
                        ZEBOIM_STATION_TARGET_MODEL_INDEX,
                    ),
                )
                assert prepared.graphics is not None
                self.assertEqual(
                    hashlib.sha256(prepared.graphics).hexdigest(),
                    ZEBOIM_STATION_FIELD_673_GRAPHICS_SHA256,
                )
                self.assertEqual(
                    (
                        gallery.south_field,
                        gallery.south_parameter,
                        gallery.north_field,
                        gallery.north_parameter,
                    ),
                    (*south, *north),
                )
                self.assertIsNone(spec.missile_gallery)
                scene = spec.auto_scene
                terminal = gallery.archive_terminal
                self.assertIsNone(scene)
                assert terminal is not None
                self.assertEqual(
                    (
                        terminal.entity,
                        terminal.dialogue_id,
                        terminal.controller_x,
                        terminal.controller_z,
                        terminal.interaction_half_width,
                    ),
                    (
                        7,
                        0,
                        ZEBOIM_STATION_VISUAL_CENTER[0],
                        0,
                        ZEBOIM_STATION_COLLISION_OPERAND,
                    ),
                )
                self.assertEqual(
                    [
                        (transition.field, transition.parameter)
                        for transition in scan_raw_transitions(transformed)
                    ],
                    [south, north],
                )
                self.assertFalse(
                    {613, 621, 710}
                    & {
                        transition.field
                        for transition in scan_raw_transitions(transformed)
                    }
                )

                # Entity 0 retains the room's native lighting/music setup.
                self.assertEqual(
                    [
                        transformed.get_script_pointer(0, index)
                        for index in range(32)
                    ],
                    [
                        donor.get_script_pointer(0, index)
                        for index in range(32)
                    ],
                )

                stop = transformed.get_script_pointer(20, 2)
                self.assertEqual(stop, 0x06A0)
                self.assertEqual(transformed.bytecode[stop], 0)

                for collider_entity, (x, _y, z) in zip(
                    WARHEAD_COLLIDER_ENTITIES,
                    WARHEAD_PLACEMENTS,
                    strict=True,
                ):
                    collider_pointer = transformed.get_script_pointer(
                        collider_entity,
                        0,
                    )
                    expected_collider = (
                        b"\x0B\x00\x80\x19"
                        + struct.pack("<hh", x, z)
                        + b"\xC0\x1A\x00\x18"
                        + bytes(
                            (
                                WARHEAD_COLLISION_OPERAND,
                                WARHEAD_COLLISION_OPERAND,
                                0xFF,
                                WARHEAD_COLLISION_OPERAND,
                            )
                        )
                        + bytes.fromhex("F8 00 10 00")
                        + b"\x23\x2A\x00"
                    )
                    self.assertEqual(
                        transformed.bytecode[
                            collider_pointer :
                            collider_pointer + len(expected_collider)
                        ],
                        expected_collider,
                    )
                    self.assertNotIn(
                        bytes.fromhex("F8 00 80 00"),
                        expected_collider,
                    )
                    self.assertEqual(
                        {
                            transformed.get_script_pointer(
                                collider_entity,
                                index,
                            )
                            for index in range(1, 32)
                        },
                        {stop},
                    )

                # Entity 6 replaces the removed cutscene with a one-shot
                # screen-layer release; entities 8/9 own warhead collision.
                # Every vault turns entity 7 into a silent-on-entry,
                # repeatable X-operated archive terminal.
                startup = transformed.get_script_pointer(6, 1)
                self.assertEqual(transformed.get_script_pointer(6, 0), 0x01AB)
                self.assertEqual(
                    transformed.bytecode[0x01AB:0x01AE],
                    bytes.fromhex("BC 2A 00"),
                )
                self.assertEqual(
                    {
                        transformed.get_script_pointer(6, index)
                        for index in range(1, 32)
                    },
                    {startup, stop},
                )

                terminal_init = transformed.get_script_pointer(7, 0)
                expected_terminal_init = _solid_station_controller_init(
                    ZEBOIM_STATION_VISUAL_CENTER[0],
                    0,
                    requires_facing=True,
                    collision_operand=ZEBOIM_STATION_COLLISION_OPERAND,
                )
                self.assertEqual(
                    transformed.bytecode[
                        terminal_init :
                        terminal_init + len(expected_terminal_init)
                    ],
                    expected_terminal_init,
                )
                self.assertEqual(expected_terminal_init[0], 0x0B)
                self.assertIn(
                    bytes.fromhex("F8 00 10 00 23 00"),
                    expected_terminal_init,
                )
                self.assertNotIn(b"\x2A", expected_terminal_init)
                self.assertEqual(
                    transformed.get_script_pointer(7, 1),
                    stop,
                )
                self.assertEqual(
                    {
                        transformed.get_script_pointer(7, index)
                        for index in range(3, 32)
                    },
                    {stop},
                )
                terminal_action = _pointed_script_body(
                    transformed,
                    transformed.get_script_pointer(7, 2),
                )
                self.assertTrue(terminal_action.startswith(b"\x33\xFE\x54"))
                self.assertEqual(terminal_action.count(_dialog(0)), 1)
                self.assertTrue(terminal_action.endswith(b"\xFE\x53\x00"))
                self.assertNotIn(b"\x98", terminal_action)
                self.assertNotIn(b"\x3B", terminal_action)
                self.assertEqual(
                    transformed.get_script_pointer(6, 1),
                    startup,
                )
                self.assertEqual(
                    transformed.bytecode[startup : startup + 14],
                    bytes.fromhex(
                        "F1 02 80 1E 80 28 80 64 80 01 80 FE 53 5B"
                    ),
                )

                for (
                    entity,
                    initializer,
                    threshold,
                    control,
                    destination,
                ) in (
                    (
                        20,
                        0x048B,
                        760,
                        0x44,
                        south,
                    ),
                    (
                        21,
                        0x051B,
                        -760,
                        0x45,
                        north,
                    ),
                ):
                    update = transformed.get_script_pointer(entity, 1)
                    self.assertEqual(
                        transformed.get_script_pointer(entity, 0),
                        initializer,
                    )
                    self.assertEqual(
                        transformed.bytecode[
                            initializer : initializer + 3
                        ],
                        bytes.fromhex("BC 2A 00"),
                    )
                    self.assertEqual(
                        transformed.get_script_pointer(entity, 1),
                        update,
                    )
                    self.assertEqual(
                        {
                            transformed.get_script_pointer(entity, index)
                            for index in range(2, 32)
                        },
                        {stop},
                    )
                    expected_poll = (
                        bytes.fromhex("2D FF F8 07 FA 07 FC 07")
                        + bytes.fromhex("02 FA 07")
                        + struct.pack("<h", threshold)
                        + bytes((control,))
                        + struct.pack("<H", update + 0x18)
                        + bytes.fromhex("FE 54")
                        + _change_field(*destination)
                        + b"\x5B\x5A"
                        + b"\x01"
                        + struct.pack("<H", update)
                    )
                    self.assertEqual(
                        transformed.bytecode[update : update + 0x1C],
                        expected_poll,
                    )

                self.assertEqual(
                    _read_field_entry(
                        transformed.to_bytes(),
                        0,
                    ),
                    FieldEntryAddition(330, 600, 0, 4, 4),
                )
                self.assertEqual(
                    _read_field_entry(
                        transformed.to_bytes(),
                        1,
                    ),
                    FieldEntryAddition(330, -600, 0, 0, 0),
                )

    def test_archive_f_crosses_stairs_before_save_point_hall(self) -> None:
        contracts = {
            (contract.field, contract.entity): contract
            for contract in VISIBLE_DOOR_CONTRACTS
        }
        expected = {
            (371, 22): (723, 0, 723, 12),
            (723, 12): (371, 0, 371, 22),
            (723, 13): (726, 8, 726, 24),
            (726, 24): (723, 1, 723, 13),
            # The post-auxiliary hub route has its own complete stairwell
            # instead of bypassing the stairs or stealing the archive route.
            (372, 22): (375, 0, 375, 12),
            (375, 12): (372, 2, 372, 22),
            (375, 13): (726, 2, 726, 15),
            (726, 15): (375, 1, 375, 13),
        }
        for key, destination in expected.items():
            with self.subTest(field=key[0], entity=key[1]):
                contract = contracts[key]
                self.assertEqual(
                    (
                        contract.destination_field,
                        contract.destination_parameter,
                        contract.reciprocal_field,
                        contract.reciprocal_entity,
                    ),
                    destination,
                )
        self.assertNotIn((371, 726), ROUTE_EDGES)
        self.assertNotIn((726, 371), ROUTE_EDGES)
        self.assertNotIn((372, 726), ROUTE_EDGES)
        self.assertNotIn((726, 372), ROUTE_EDGES)

