    def test_prepared_control_overlays_are_runtime_safe_and_x_enabled(self) -> None:
        project = REPOSITORY_ROOT
        field = _prepare_field_overlay(project / "work")
        self.assertEqual(
            hashlib.sha256(field.bundle).hexdigest(),
            FIELD_OVERLAY_PACKED_SHA256,
        )
        field_decoded = decompress_lzss(
            field.bundle,
            260862,
        ).data
        self.assertEqual(
            hashlib.sha256(field_decoded).hexdigest(),
            FIELD_OVERLAY_CROSS_ONLY_SHA256,
        )

        worldmap = _prepare_worldmap_controls(project / "work")
        self.assertEqual(
            hashlib.sha256(worldmap.bundle).hexdigest(),
            WORLDMAP_CONTROL_PATCHED_SHA256,
        )
        retail_worldmap = decompress_worldmap(
            (project / "work" / "worldmap_audit" / "0037.bin").read_bytes()
        )
        patched_worldmap = decompress_worldmap(worldmap.bundle)
        changed = {
            index
            for index, (before, after) in enumerate(
                zip(retail_worldmap, patched_worldmap, strict=True)
            )
            if before != after
        }
        self.assertEqual(changed, {0x5780, 0x6586})
        self.assertEqual(
            patched_worldmap[0x210A4 : 0x210A8],
            bytes.fromhex("20 00 42 30"),
        )
        self.assertEqual(
            patched_worldmap[0x5780 : 0x5784],
            bytes.fromhex("01 00 02 24"),
        )
        self.assertEqual(
            patched_worldmap[0x6584 : 0x6588],
            bytes.fromhex("08 95 20 A0"),
        )

        entry = _prepare_worldmap(project / "work")
        self.assertEqual(
            hashlib.sha256(entry.bundle).hexdigest(),
            WORLDMAP_PATCHED_SHA256,
        )
        entry_decoded = decompress_worldmap(entry.bundle)
        self.assertEqual(
            hashlib.sha256(entry_decoded).hexdigest(),
            WORLDMAP_PATCHED_DECODED_SHA256,
        )
        self.assertEqual(
            entry_decoded[MASS_DRIVER_ENCOUNTER_ENEMY_OFFSET],
            MASS_DRIVER_ENCOUNTER_DRAGON_SELECTOR,
        )

    def test_retail_mass_driver_cinematic_has_a_party_safe_mod_return(self) -> None:
        project = REPOSITORY_ROOT
        prepared = _prepare_mass_driver_launch_scene(project / "work")
        self.assertEqual(
            prepared.bundle_id,
            MASS_DRIVER_LAUNCH_SCENE_BUNDLE_ID,
        )

        source = parse_field(
            (
                project
                / "work"
                / "target_chain"
                / f"{MASS_DRIVER_LAUNCH_SCENE_BUNDLE_ID}.bin"
            ).read_bytes()
        )
        rebuilt = parse_field(prepared.bundle)
        for index in range(len(source.parts)):
            with self.subTest(component=index):
                if index == SCRIPT_INDEX:
                    self.assertNotEqual(
                        source.parts[index].data,
                        rebuilt.parts[index].data,
                    )
                else:
                    self.assertEqual(
                        source.parts[index].data,
                        rebuilt.parts[index].data,
                    )

        retail = AtelScript(source.parts[SCRIPT_INDEX].data)
        patched = AtelScript(rebuilt.parts[SCRIPT_INDEX].data)
        self.assertEqual(
            retail.get_script_pointer(9, 1),
            MASS_DRIVER_LAUNCH_SCENE_UPDATE_POINTER,
        )
        self.assertEqual(
            retail.bytecode[0x084F : 0x084F + 10],
            _worldmap(
                MASS_DRIVER_LAUNCH_SCENE_POSITION,
                MASS_DRIVER_LAUNCH_SCENE_MODE,
            ),
        )
        wrapper_pointer = patched.get_script_pointer(9, 1)
        self.assertGreaterEqual(wrapper_pointer, retail.bytecode_size)
        wrapper = patched.bytecode[wrapper_pointer:]
        self.assertEqual(
            wrapper[:6],
            bytes.fromhex("02 02 00 02 00 40"),
        )
        self.assertIn(
            bytes.fromhex("02 FE 03 40 00 46"),
            wrapper,
        )
        safe_return = (
            _clear_var_bit(
                RETAIL_WORLDMAP_RETURN_VARIABLE,
                RETAIL_WORLDMAP_RETURN_BIT,
            )
            + bytes.fromhex("FE 19 02")
            + _change_field(
                mass_driver.MASS_DRIVER_GEAR_RECOVERY_FIELD,
                mass_driver.MASS_DRIVER_GEAR_RECOVERY_PARAMETER,
            )
            + b"\x5B"
        )
        self.assertIn(safe_return, wrapper)
        self.assertEqual(wrapper.count(bytes.fromhex("FE 19 02")), 1)
        self.assertLess(
            wrapper.index(bytes.fromhex("FE 19 02")),
            wrapper.index(_change_field(384, 1)),
        )
        self.assertTrue(
            wrapper.endswith(
                b"\x01"
                + struct.pack(
                    "<H",
                    MASS_DRIVER_LAUNCH_SCENE_UPDATE_POINTER,
                )
            )
        )
        # Retail entity-32 script 4 removes the full party.  The guarded mod
        # return removes only temporary launch-assistant Citan, restoring the
        # dungeon's Elly/Emeralda roster before playable control resumes.
        self.assertNotIn(bytes.fromhex("09 20 24"), wrapper)

    def test_postlaunch_gear_recovery_is_isolated_from_battle_and_revisits(self) -> None:
        _donor, hall = _donor_and_transformed(384)
        scene = _clone(384).goliath_factory_hall
        assert scene is not None
        pc = hall.get_script_pointer(scene.director_entity, 1)
        routine = _pointed_script_body(hall, pc)
        # Both the dedicated arrival parameter and successful launch are
        # required. A normal visit or incomplete launch branches past recovery.
        self.assertEqual(routine[:6], bytes.fromhex("02 02 00 01 00 40"))
        self.assertEqual(routine[8:14], bytes.fromhex("02 FE 03 40 00 46"))
        normal_pc = struct.unpack_from("<H", routine, 6)[0]
        self.assertEqual(struct.unpack_from("<H", routine, 14)[0], normal_pc)
        ending = routine[16 : normal_pc - pc]
        normal = routine[normal_pc - pc :]
        arrival = mass_driver._read_field_entry(hall.to_bytes(), 1)
        self.assertEqual(arrival, FieldEntryAddition(0, -2100, 0, 0, 0))
        departure = _worldmap(21, 1)
        self.assertTrue(ending.endswith(departure + b"\x5B"))
        self.assertNotIn(_fixed_battle(scene.battle.configuration), ending)
        self.assertNotIn(departure, normal)
        self.assertNotIn(_dialogue_sequence((7,)), normal)
        for slot, character, gear, staged_bit in (
            (0, 1, mass_driver.VIERGE_GEAR_ID, mass_driver.ELLY_GEAR_STAGED_BIT),
            (1, 6, 9, CRESCENS_STAGED_BIT),
        ):
            assignment = b"\xFE\xA1" + struct.pack("<HH", character | 0x8000, gear | 0x8000)
            mount = b"\xFE\x41" + struct.pack("<H", slot | 0x8000)
            staged = _set_var_bit(INTERLOCK_VARIABLE, staged_bit)
            self.assertLess(ending.index(assignment), ending.index(mount))
            self.assertLess(ending.index(mount), ending.index(staged))
            self.assertLess(ending.index(staged), ending.index(departure))
        # Completion/history/authorization are retained; recovery only adds
        # the two existing mounted-party markers and never resets the route.
        self.assertNotIn(_clear_var_bit(INTERLOCK_VARIABLE, LAUNCH_COMPLETED_BIT), ending)

