    def test_interlock_interaction_sets_one_persistent_bit_before_dialogue(
        self,
    ) -> None:
        # Operand 0x03FE addresses fieldVars[0x1FF], the final word copied
        # to/from GameState. Operands at or above 0x0400 are field-local.
        self.assertEqual(INTERLOCK_VARIABLE, 0x03FE)
        self.assertEqual(
            _jump_if_bit_clear(INTERLOCK_VARIABLE, 1, 0x1234),
            bytes.fromhex("02 fe 03 01 00 46 34 12"),
        )
        self.assertEqual(
            _set_var_bit(INTERLOCK_VARIABLE, RAIL_INTERLOCK_BIT),
            bytes.fromhex("3a fe 03 01 00 40"),
        )
        with self.assertRaisesRegex(DungeonBuildError, "bit index"):
            _set_var_bit(INTERLOCK_VARIABLE, 16)
        with self.assertRaisesRegex(DungeonBuildError, "bit mask"):
            _jump_if_bit_clear(INTERLOCK_VARIABLE, 0, 0x1234)

        source = bytearray(_script(b"\xBC\x00"))
        struct.pack_into("<H", source, 0x88, 1)
        result = _install_interlock_interaction(
            bytes(source),
            InterlockInteraction(
                0,
                1,
                2,
                INTERLOCK_VARIABLE,
                RAIL_INTERLOCK_BIT,
            ),
        )
        parsed = AtelScript(result)
        pointer = parsed.get_script_pointer(0, 2)

        self.assertEqual(pointer, 2)
        self.assertEqual(
            parsed.bytecode[pointer:],
            bytes.fromhex(
                "3a fe 03 01 00 40 "
                "33 fe 54 "
                "31 20 00 16 00 26 01 80 01 0b 00 "
                "26 01 80 "
                "f5 02 00 00 9c fe 53 00"
            ),
        )
        self.assertEqual(scan_raw_transitions(ParsedAtelScript(result)), [])

        sounded = _install_interlock_interaction(
            bytes(source),
            InterlockInteraction(
                0,
                1,
                2,
                INTERLOCK_VARIABLE,
                RAIL_INTERLOCK_BIT,
                0x50,
            ),
        )
        sounded_script = AtelScript(sounded)
        sounded_pointer = sounded_script.get_script_pointer(0, 2)
        self.assertEqual(
            sounded_script.bytecode[sounded_pointer : sounded_pointer + 9],
            _set_var_bit(INTERLOCK_VARIABLE, RAIL_INTERLOCK_BIT)
            + bytes.fromhex("74 50 80"),
        )

    def test_clue_overviews_require_deliberate_read_and_preserve_progress(
        self,
    ) -> None:
        configured = [
            (spec, interaction)
            for spec in CLONES
            for interaction in spec.interlock_interactions
            if interaction.summary_dialogue_id is not None
        ]
        self.assertEqual(
            [(spec.target_field, item.entity) for spec, item in configured],
            [(361, 16), (722, 14)],
        )
        for spec, interaction in configured:
            _, script = _donor_and_transformed(spec.target_field)
            start = script.get_script_pointer(interaction.entity, 2)
            body = _pointed_script_body(script, start)
            # Record access must neither move the party nor start a battle.
            self.assertEqual(scan_raw_transitions(ParsedAtelScript(_script(body))), [])
            menu = _choice_dialog(interaction.record_menu_dialogue_id) + b"\xA9\x12\x9C"
            self.assertEqual(body.count(menu), 1)
            menu_offset = body.index(menu)
            self.assertIn(_dialog(interaction.summary_dialogue_id), body[:menu_offset])
            self.assertNotIn(_dialog(interaction.dialogue_id), body[:menu_offset])
            # Every entry and transition to a new window drains held Cross.
            self.assertEqual(body.count(b"\x31\x20\x00"), 3)

            for prior in (0, 1 << interaction.bit_index, 0xFFFF ^ (1 << interaction.bit_index)):
                for choice in (1, 2, 0, 0xFFFF):
                    with self.subTest(field=spec.target_field, prior=prior, choice=choice):
                        # Follow the emitted ATEL branch and bit-write semantics,
                        # with released input and a native menu result. Reject any
                        # new unreviewed opcode or write instead of skipping it.
                        variables = {INTERLOCK_VARIABLE: prior, 0x03FC: 0xA55A}
                        shown = []
                        controls = []
                        pc = start
                        for _ in range(100):
                            code = script.bytecode
                            opcode = code[pc]
                            if opcode == 0x00:
                                break
                            if opcode == 0x3A:
                                variable, bit_index = struct.unpack_from("<HH", code, pc + 1)
                                self.assertEqual(code[pc + 5], 0x40)
                                variables[variable] = variables.get(variable, 0) | (1 << bit_index)
                                pc += 6
                            elif opcode == 0x02:
                                variable, value, control, destination = struct.unpack_from("<HHBH", code, pc + 1)
                                self.assertEqual((variable, control), (0x0014, 0x40))
                                pc = destination if variables[variable] != value else pc + 8
                            elif opcode == 0x31:
                                # Released held-pad mask follows the native false target.
                                pc = struct.unpack_from("<H", code, pc + 3)[0]
                            elif opcode == 0x26:
                                pc += 3
                            elif opcode == 0x33:
                                pc += 1
                            elif opcode == 0xF4:
                                self.assertEqual(code[pc + 1], 1)
                                pc += 2
                            elif opcode == 0xFE:
                                operation = code[pc + 1]
                                if operation in (0x53, 0x54):
                                    controls.append(operation)
                                    pc += 2
                                else:
                                    self.assertEqual(code[pc : pc + 4], b"\xFE\x0D\xFC\x80")
                                    pc += 4
                            elif opcode in (0xF5, 0xD2):
                                shown.append(struct.unpack_from("<H", code, pc + 1)[0])
                                pc += 4
                            elif opcode == 0xA9:
                                self.assertEqual(code[pc + 1], 0x12)
                                variables[0x0014] = choice
                                pc += 2
                            elif opcode == 0x9C:
                                pc += 1
                            else:
                                self.fail(f"Unreviewed clue opcode {opcode:#x} at {pc:#x}")
                        else:
                            self.fail("Clue interaction failed to return")
                        self.assertEqual(
                            shown,
                            [interaction.summary_dialogue_id, interaction.record_menu_dialogue_id]
                            + ([interaction.dialogue_id] if choice == 2 else []),
                        )
                        self.assertEqual(controls, [0x54, 0x53])
                        self.assertEqual(
                            variables,
                            {INTERLOCK_VARIABLE: prior | (1 << interaction.bit_index),
                             0x03FC: 0xA55A, 0x0014: choice},
                        )

        source = bytearray(_script(b"\xBC\x00"))
        struct.pack_into("<H", source, 0x88, 1)
        for options in ({"summary_dialogue_id": 2}, {"record_menu_dialogue_id": 3}):
            with self.subTest(incomplete_overview=options):
                with self.assertRaisesRegex(DungeonBuildError, "both summary and menu"):
                    _install_interlock_interaction(
                        bytes(source),
                        InterlockInteraction(0, 1, 0, INTERLOCK_VARIABLE, DIRECTIVE_RECORD_BIT, **options),
                    )

