    def test_storage_annex_native_treasure_awards_omegasol_once(
        self,
    ) -> None:
        spec = _clone(722)
        chest = spec.storage_annex_treasure_chest
        assert chest is not None
        self.assertEqual(OMEGASOL_ITEM_ID, 49)
        self.assertEqual(STORAGE_ANNEX_CHEST_OPENED_BIT, 14)
        self.assertEqual(STORAGE_ANNEX_CHEST_OPENED_MASK, 0x4000)
        self.assertEqual(
            (
                chest.entity,
                chest.old_init_pointer,
                chest.old_update_pointer,
                chest.old_action_pointer,
                chest.old_collision_pointer,
                chest.item_variable,
                chest.item_initialization_pc,
                chest.old_item_id,
                chest.item_id,
                chest.old_opened_variable,
                chest.old_opened_bit,
                chest.opened_variable,
                chest.opened_bit,
                chest.opened_check_pc,
                chest.opened_check_clear_target,
                chest.opened_write_pc,
            ),
            (
                15,
                0x019D,
                0x01E6,
                0x01E7,
                0x0241,
                0x041E,
                0x0059,
                5,
                49,
                0x0162,
                3,
                INTERLOCK_VARIABLE,
                14,
                0x005F,
                0x006A,
                0x006D,
            ),
        )

        donor, transformed = _donor_and_transformed(722)
        native_pointers = (0x019D, 0x01E6, 0x01E7, 0x0241)
        self.assertEqual(
            tuple(donor.get_script_pointer(15, index) for index in range(4)),
            native_pointers,
        )
        self.assertEqual(
            tuple(
                transformed.get_script_pointer(15, index)
                for index in range(4)
            ),
            native_pointers,
        )
        self.assertEqual(transformed.get_script_pointer(0, 4), 0x006D)

        old_item_assignment = bytes.fromhex("35 1E 04 05 00 40")
        omegasol_assignment = bytes.fromhex("35 1E 04 31 00 40")
        self.assertEqual(
            donor.bytecode[0x0059:0x005F],
            old_item_assignment,
        )
        self.assertEqual(
            transformed.bytecode[0x0059:0x005F],
            omegasol_assignment,
        )
        old_opened_check = _jump_if_bit_clear(0x0162, 0x0008, 0x006A)
        new_opened_check = _jump_if_bit_clear(
            INTERLOCK_VARIABLE,
            STORAGE_ANNEX_CHEST_OPENED_MASK,
            0x006A,
        )
        self.assertEqual(donor.bytecode[0x005F:0x0067], old_opened_check)
        self.assertEqual(
            transformed.bytecode[0x005F:0x0067],
            new_opened_check,
        )
        old_opened_write = _set_var_bit(0x0162, 3)
        new_opened_write = _set_var_bit(
            INTERLOCK_VARIABLE,
            STORAGE_ANNEX_CHEST_OPENED_BIT,
        )
        self.assertEqual(donor.bytecode[0x006D:0x0073], old_opened_write)
        self.assertEqual(
            transformed.bytecode[0x006D:0x0073],
            new_opened_write,
        )
        self.assertEqual(transformed.bytecode.count(new_opened_check), 1)
        self.assertEqual(transformed.bytecode.count(new_opened_write), 1)

        native_init = donor.bytecode[0x019D:0x01E6]
        native_action = donor.bytecode[0x01E7:0x0241]
        self.assertEqual(
            transformed.bytecode[0x019D:0x01E6],
            native_init,
        )
        self.assertEqual(
            transformed.bytecode[0x01E7:0x0241],
            native_action,
        )
        self.assertEqual(
            hashlib.sha256(native_init).hexdigest(),
            "b96a676d57e16926e7bcfab06bdd776d"
            "a8f1b9fdcf68470f040a2a7536a44f8a",
        )
        self.assertEqual(
            hashlib.sha256(native_action).hexdigest(),
            "7a9ff15926d4236dfdf64b6d662b44e"
            "aee76514893eab3b39ef965ed100447c9",
        )
        # The retail routine keeps its capacity-failure and receipt windows,
        # inventory award, opening animation, and final opened-object hide.
        self.assertEqual(
            native_action.count(bytes.fromhex("D2 00 00 01 9C")),
            1,
        )
        self.assertEqual(
            native_action.count(bytes.fromhex("D2 01 00 01 9C")),
            1,
        )
        self.assertEqual(native_action.count(bytes.fromhex("09 00 24")), 1)
        self.assertEqual(
            native_action.count(b"\x8C" + struct.pack("<H", 0x041E)),
            1,
        )
        self.assertEqual(
            native_action.count(
                bytes.fromhex(
                    "D0 00 80 00 80 10 80 03 80 00 80"
                )
            ),
            1,
        )
        self.assertEqual(native_action[-3:], bytes((0x29, 15, 0x00)))

    def test_annex_368_native_console_controls_accelerator_rail(self) -> None:
        project = REPOSITORY_ROOT
        spec = _clone(368)
        self.assertEqual(
            spec.optional_interactions,
            (
                OptionalInteraction(
                    14,
                    0x0313,
                    1,
                    old_init_pointer=0x030F,
                    fixed_script_position=(-124, -25),
                    controller_requires_facing=False,
                    controller_interaction_half_width=0x08,
                ),
            ),
        )
        self.assertEqual(
            spec.interlock_interactions,
            (
                InterlockInteraction(
                    13,
                    0x02E6,
                    0,
                    INTERLOCK_VARIABLE,
                    RAIL_INTERLOCK_BIT,
                    0x50,
                    old_init_pointer=0x02CD,
                    fixed_script_position=(45, -42),
                    controller_requires_facing=False,
                    controller_interaction_half_width=0x1E,
                ),
            ),
        )
        hanging = spec.optional_interactions[0]
        rail = spec.interlock_interactions[0]
        hanging_reach = hanging.controller_interaction_half_width * 2 + 16
        rail_reach = rail.controller_interaction_half_width * 2 + 16
        live_position = (-124.0753936768, -24.5514526367)
        self.assertEqual((hanging_reach, rail_reach), (32, 76))
        self.assertTrue(
            abs(live_position[0] - hanging.fixed_script_position[0])
            <= hanging_reach
            and abs(live_position[1] - hanging.fixed_script_position[1])
            <= hanging_reach
        )
        self.assertGreater(abs(live_position[1] - 90), 76)
        self.assertEqual(
            abs(rail.fixed_script_position[0] - hanging.fixed_script_position[0])
            - rail_reach
            - hanging_reach,
            61,
        )
        # (-124,-25) is strictly inside layer-0 triangle 16. These exact
        # positive weights correspond to vertices (-129,-28), (-106,-5), and
        # (-80,-1), proving that the rounded script coordinate is walkable.
        self.assertTrue(
            all(weight > 0 for weight in (224 / 253, 6 / 253, 1 / 11))
        )

        donor, transformed = _donor_and_transformed(368)
        self.assertEqual(
            tuple(donor.get_script_pointer(13, index) for index in range(4)),
            (0x02CD, 0x02E5, 0x02E6, 0x030E),
        )
        self.assertEqual(
            transformed.bytecode[0x02CD : 0x02CD + 24],
            bytes.fromhex(
                "BC 19 2D 00 D6 FF C0 "
                "F8 00 00 20 F8 03 04 00 "
                "18 14 14 64 00 20 01 80 00"
            ),
        )
        rail_init = transformed.get_script_pointer(13, 0)
        self.assertNotEqual(rail_init, 0x02CD)
        self.assertEqual(
            _pointed_script_body(transformed, rail_init),
            _static_door_controller_init(
                45,
                -42,
                requires_facing=False,
                interaction_half_width=0x1E,
            ),
        )
        self.assertEqual(transformed.get_script_pointer(13, 1), 0x02E5)
        self.assertEqual(transformed.get_script_pointer(13, 3), 0x030E)
        action = transformed.get_script_pointer(13, 2)
        self.assertEqual(
            transformed.bytecode[action : action + 9],
            _set_var_bit(INTERLOCK_VARIABLE, RAIL_INTERLOCK_BIT)
            + bytes.fromhex("74 50 80"),
        )
        self.assertEqual(
            transformed.bytecode.count(
                _set_var_bit(INTERLOCK_VARIABLE, RAIL_INTERLOCK_BIT)
            ),
            1,
        )
        self.assertEqual(
            tuple(donor.get_script_pointer(14, index) for index in range(4)),
            (0x030F, 0x0312, 0x0313, 0x0314),
        )
        self.assertEqual(
            transformed.get_script_pointer(14, 1),
            0x0312,
        )
        self.assertEqual(
            transformed.get_script_pointer(14, 3),
            0x0314,
        )
        rear_init = transformed.get_script_pointer(14, 0)
        self.assertEqual(
            _pointed_script_body(transformed, rear_init),
            _static_door_controller_init(
                -124,
                -25,
                requires_facing=False,
                interaction_half_width=0x08,
            ),
        )
        rear_action = transformed.get_script_pointer(14, 2)
        rear_body = _pointed_script_body(transformed, rear_action)
        self.assertIn(_dialog(1), rear_body)
        self.assertNotIn(
            _set_var_bit(INTERLOCK_VARIABLE, RAIL_INTERLOCK_BIT),
            rear_body,
        )

        header, components = _load_components(
            project / "work" / spec.bundle_directory
        )
        prepared = _prepare_clone(
            spec,
            project / "work",
            project / "modules" / "mass_driver" / "content",
        )
        self.assertEqual(prepared.header, header)
        self.assertEqual(prepared.components[MODEL_INDEX], components[MODEL_INDEX])
        model_entries = _indexed_bundle_entries(components[MODEL_INDEX])
        self.assertEqual(
            struct.unpack_from("<HhhhhhhH", header, 0x190 + 24 * 16),
            (0x0010, 0, 0x0600, 0, 0, 0, 0, 3),
        )
        self.assertEqual(
            struct.unpack_from("<HhhhhhhH", header, 0x190 + 25 * 16),
            (0x0010, 0, 0x0600, 0, 0, 0, 0, 4),
        )
        self.assertEqual(
            hashlib.sha256(model_entries[3]).hexdigest(),
            "4295f313e5fd54f3cb496ea050bcb3f3"
            "8234298d1e8522f0e5a673f081efab8b",
        )
        self.assertEqual(
            hashlib.sha256(model_entries[4]).hexdigest(),
            "56625491e9d7d52225e3391cf6fe7cd9"
            "05b6a59a2d54f80329b2a2403bfe8aed",
        )
        self.assertEqual(
            struct.unpack_from(
                "<hhhh",
                components[1],
                0x150 + 7 * 8,
            ),
            (41, -2, -35, 0),
        )
        self.assertEqual(
            struct.unpack_from(
                "<hhhh",
                components[1],
                0x150 + 19 * 8,
            ),
            (-70, -3, 74, 0),
        )
        self.assertEqual(
            hashlib.sha256(model_entries[13]).hexdigest(),
            "e1ac9cf7e068e0f599f540a68cbe744a"
            "ef8d28520937acda71d0c3f9cc47996e",
        )
        self.assertEqual(
            hashlib.sha256(model_entries[14]).hexdigest(),
            "be8202aa8223397dc634793f391dd070d"
            "e42008520dc2238e3539c48bbbe07d7",
        )

    def test_annex_368_splits_rail_feedback_from_rear_terminal_mail(
        self,
    ) -> None:
        source = (
            REPOSITORY_ROOT
            / "modules" / "mass_driver" / "content"
            / "field_368_archive_annex.authored.json"
        )
        document = json.loads(source.read_text(encoding="utf-8"))
        blocks = {block["id"]: block for block in document["blocks"]}
        self.assertEqual(tuple(blocks), (0, 1))
        rail = blocks[0]["text"]
        mail = blocks[1]["text"]
        self.assertIn("ACCELERATOR INTERLOCK", rail)
        normalized_rail = " ".join(rail.replace("<New>", " ").split())
        self.assertIn("Accelerator supply restored", normalized_rail)
        self.assertIn("Accelerator power requirement satisfied", normalized_rail)
        self.assertNotIn("ARCHIVED SHIFT LOG", rail)
        normalized_mail = " ".join(mail.replace("<New>", " ").split())
        for phrase in (
            "ACCELERATOR SERVICE RECORD", "ARCHIVED SHIFT LOG / 6081",
            "OPERATOR: ARON", "ARON / TO: LENA", "thermal limit",
            "bypassing the thermal cutoff", "Bypass fitted by Aron",
        ):
            self.assertIn(phrase, normalized_mail)
        self.assertNotIn("Accelerator supply restored", normalized_mail)

