    def test_objective_progression_uses_seven_nonoverlapping_persistent_bits(
        self,
    ) -> None:
        progression = (
            (AUXILIARY_INTERLOCK_BIT, AUXILIARY_INTERLOCK_MASK),
            (RAIL_INTERLOCK_BIT, RAIL_INTERLOCK_MASK),
            (DIRECTIVE_RECORD_BIT, DIRECTIVE_RECORD_MASK),
            (ADDRESS_RECORD_BIT, ADDRESS_RECORD_MASK),
            (LAUNCH_AUTHORIZATION_BIT, LAUNCH_AUTHORIZATION_MASK),
            (BOSS_DEFEATED_BIT, BOSS_DEFEATED_MASK),
            (LAUNCH_COMPLETED_BIT, LAUNCH_COMPLETED_MASK),
        )
        self.assertEqual(
            progression,
            tuple((bit, 1 << bit) for bit in range(7)),
        )
        self.assertEqual(
            sum(mask for _, mask in progression),
            0x7F,
        )

    def test_staging_tracks_each_gear_in_its_own_persistent_free_bit(
        self,
    ) -> None:
        staged = (
            (EL_REGULUS_STAGED_BIT, EL_REGULUS_STAGED_MASK),
            (CRESCENS_STAGED_BIT, CRESCENS_STAGED_MASK),
        )
        self.assertEqual(staged, ((11, 0x0800), (15, 0x8000)))
        self.assertEqual(
            staged,
            tuple((bit, 1 << bit) for bit, _mask in staged),
        )
        self.assertEqual(
            sum(mask for _, mask in staged) & 0x7F,
            0,
        )

