    def test_el_regulus_battle_entry_keeps_native_target_facing(self) -> None:
        project = REPOSITORY_ROOT
        source = (
            project
            / "work"
            / "_audit_el_regulus_battle"
            / f"{EL_REGULUS_BATTLE_ANIMATION_CANONICAL_ID}.bin"
        ).read_bytes()
        patched = _patch_el_regulus_battle_entry_animation(source)
        self.assertEqual(EL_REGULUS_BATTLE_ANIMATION_CANONICAL_ID, 2960)
        self.assertEqual(
            hashlib.sha256(source).hexdigest(),
            EL_REGULUS_BATTLE_ANIMATION_SOURCE_SHA256,
        )
        self.assertEqual(
            (len(patched), hashlib.sha256(patched).hexdigest()),
            (
                33_608,
                "dbdbad3dd937dbbb80b5569000a79ad82d9bf70943af5dd35ed5af7f2f5c4c90",
            ),
        )
        self.assertEqual(
            EL_REGULUS_BATTLE_ANIMATION_PATCHED_SHA256,
            "dbdbad3dd937dbbb80b5569000a79ad82d9bf70943af5dd35ed5af7f2f5c4c90",
        )
        self.assertEqual(
            struct.unpack_from("<4I", source, 0),
            (2, *EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS),
        )
        self.assertEqual(
            struct.unpack_from("<4I", patched, 0),
            (2, *EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS),
        )
        self.assertEqual(
            EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS,
            (0x10, 0x7FFC, 0x8348),
        )
        self.assertEqual(
            len(patched) - len(source),
            EL_REGULUS_BATTLE_ANIMATION_DELTA,
        )
        self.assertEqual(EL_REGULUS_BATTLE_ANIMATION_DELTA, 0x708)
        source_entry = _el_regulus_battle_animation_program(source, 0)
        patched_entry = _el_regulus_battle_animation_program(patched, 0)
        # Animation 0 begins at 0x71BC. Derive that checked archive pointer
        # instead of treating the absolute location as an unexplained literal.
        source_main = EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[0]
        source_entry_start = source_main + struct.unpack_from(
            "<I", source, source_main + 8
        )[0]
        relative_target = (
            EL_REGULUS_BATTLE_ENTRY_NATIVE_TARGET_OFFSET - source_entry_start
        )
        relative_tail = source_entry.index(
            EL_REGULUS_BATTLE_ENTRY_SOURCE_TAIL
        )
        self.assertEqual(
            source_entry[
                relative_target : relative_target
                + len(EL_REGULUS_BATTLE_ENTRY_NATIVE_TARGET_FACING)
            ],
            EL_REGULUS_BATTLE_ENTRY_NATIVE_TARGET_FACING,
        )
        self.assertEqual(
            patched_entry[
                relative_target + len(EL_REGULUS_AERODS_INITIAL_HIDE) :
                relative_target
                + len(EL_REGULUS_AERODS_INITIAL_HIDE)
                + len(EL_REGULUS_BATTLE_ENTRY_NATIVE_TARGET_FACING)
            ],
            EL_REGULUS_BATTLE_ENTRY_NATIVE_TARGET_FACING,
        )
        self.assertEqual(len(source_entry), 32)
        self.assertEqual(EL_REGULUS_BATTLE_ENTRY_IDLE_DELTA, 4)
        self.assertEqual(
            len(patched_entry) - len(source_entry),
            EL_REGULUS_BATTLE_ENTRY_IDLE_DELTA
            + len(EL_REGULUS_AERODS_INITIAL_HIDE),
        )
        self.assertEqual(
            patched_entry,
            bytes.fromhex(
                "0A 00 0C 00 23 80 3C 00 "
                "10 00 48 00 4A FD 61 00 0A 00 5A 08 "
                "32 00 06 00 60 00 43 00 10 FF 21 00 6D 00 "
                "11 FF 00 01 00 00"
            ),
        )
        completion_handshake = EL_REGULUS_BATTLE_ENTRY_COMPLETION_TAIL[:-2]
        terminator = EL_REGULUS_BATTLE_ENTRY_COMPLETION_TAIL[-2:]
        self.assertEqual(completion_handshake, bytes.fromhex("21 00 6D 00"))
        self.assertEqual(
            EL_REGULUS_BATTLE_ENTRY_IDLE_LOOP,
            EL_REGULUS_BATTLE_ENTRY_SOURCE_TAIL[:-2],
        )
        patched_tail = relative_tail + len(EL_REGULUS_AERODS_INITIAL_HIDE)
        self.assertEqual(
            patched_entry[
                patched_tail : patched_tail
                + len(completion_handshake)
            ],
            completion_handshake,
        )
        self.assertEqual(
            patched_entry[
                patched_tail
                + len(completion_handshake) : patched_tail
                + len(completion_handshake)
                + len(EL_REGULUS_BATTLE_ENTRY_IDLE_LOOP)
            ],
            EL_REGULUS_BATTLE_ENTRY_IDLE_LOOP,
        )
        self.assertEqual(
            patched_entry[-len(terminator) :],
            terminator,
        )

        # Crescens uses the same formation-target setup in its untouched
        # retail animation 0.  Keep this as an external playable-Gear
        # reference so a model-local manual turn cannot return unnoticed.
        crescens = (
            project / "work" / "_audit_el_regulus_battle" / "2958.bin"
        ).read_bytes()
        crescens_main = struct.unpack_from("<I", crescens, 4)[0]
        crescens_entry_start, crescens_entry_end = (
            crescens_main + relative
            for relative in struct.unpack_from(
                "<II", crescens, crescens_main + 8
            )
        )
        crescens_entry = crescens[crescens_entry_start:crescens_entry_end]
        native_setup = bytes.fromhex(
            "61 00 0A 00 5A 08 32 00 06 00 60 00 43 00"
        )
        self.assertEqual(patched_entry.count(native_setup), 1)
        self.assertEqual(crescens_entry.count(native_setup), 1)

        # Animation 4 owns the common post-action return for attacks and
        # deathblows.  El-Regulus uniquely returned home without the native
        # slot-center reacquire/face pair used by the other playable Gears.
        source_post_action = _el_regulus_battle_animation_program(
            source, EL_REGULUS_POST_ACTION_ANIMATION_ID
        )
        patched_post_action = _el_regulus_battle_animation_program(
            patched, EL_REGULUS_POST_ACTION_ANIMATION_ID
        )
        self.assertEqual(
            (
                len(source_post_action),
                hashlib.sha256(source_post_action).hexdigest(),
            ),
            (
                EL_REGULUS_POST_ACTION_SOURCE_SIZE,
                EL_REGULUS_POST_ACTION_SOURCE_SHA256,
            ),
        )
        self.assertEqual(
            (
                len(patched_post_action),
                hashlib.sha256(patched_post_action).hexdigest(),
            ),
            (
                EL_REGULUS_POST_ACTION_PATCHED_SIZE,
                EL_REGULUS_POST_ACTION_PATCHED_SHA256,
            ),
        )
        return_home = bytes.fromhex("4A FD 5B 02")
        self.assertEqual(source_post_action.count(return_home), 1)
        self.assertEqual(
            patched_post_action,
            source_post_action.replace(
                return_home,
                bytes.fromhex("4A FD")
                + EL_REGULUS_POST_ACTION_NATIVE_REFACE
                + bytes.fromhex("5B 02"),
            ),
        )
        self.assertEqual(
            patched_post_action.count(
                bytes.fromhex("4A FD")
                + EL_REGULUS_POST_ACTION_NATIVE_REFACE
                + bytes.fromhex("5B 02")
            ),
            1,
        )
        crescens_post_pointer = (
            crescens_main
            + 4 * (EL_REGULUS_POST_ACTION_ANIMATION_ID + 2)
        )
        crescens_post_start, crescens_post_end = (
            crescens_main + relative
            for relative in struct.unpack_from(
                "<II", crescens, crescens_post_pointer
            )
        )
        crescens_post_action = crescens[
            crescens_post_start:crescens_post_end
        ]
        self.assertIn(native_setup, crescens_post_action)
        self.assertIn(
            EL_REGULUS_POST_ACTION_NATIVE_REFACE,
            crescens_post_action,
        )
        self.assertEqual(
            patched[
                EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1] :
                EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[2]
            ],
            source[
                EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[1] :
                EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[2]
            ],
        )
        for animation_id, expected_size, expected_hash, clip in zip(
            EL_REGULUS_ATTACK_ANIMATION_IDS,
            EL_REGULUS_ATTACK_ANIMATION_PATCHED_SIZES,
            EL_REGULUS_ATTACK_ANIMATION_PATCHED_SHA256,
            (0x40, 0x41, 0x42),
            strict=True,
        ):
            with self.subTest(animation_id=animation_id):
                program = _el_regulus_battle_animation_program(
                    patched, animation_id
                )
                self.assertEqual(len(program), expected_size)
                self.assertEqual(hashlib.sha256(program).hexdigest(), expected_hash)
                self.assertTrue(
                    program.startswith(
                        bytes.fromhex("05 00 0A 00 0C 00 58 FF 43 01")
                    )
                )
                self.assertEqual(program.count(bytes.fromhex("43 01")), 1)
                self.assertIn(
                    bytes((0x13, 0x00, clip, 0x00)),
                    program,
                )
                self.assertEqual(program.count(bytes.fromhex("3F 00")), 1)
                self.assertIn(bytes.fromhex("3A 00 02 00 00 00"), program)

        source_aerods = _el_regulus_battle_animation_program(
            source,
            EL_REGULUS_AERODS_ANIMATION_ID,
        )
        patched_aerods = _el_regulus_battle_animation_program(
            patched,
            EL_REGULUS_AERODS_ANIMATION_ID,
        )
        self.assertEqual(source_aerods, EL_REGULUS_AERODS_RETURN_STUB)
        self.assertEqual(
            hashlib.sha256(source_aerods).hexdigest(),
            EL_REGULUS_AERODS_RETURN_STUB_SHA256,
        )
        self.assertEqual(
            (
                len(patched_aerods),
                hashlib.sha256(patched_aerods).hexdigest(),
            ),
            (
                EL_REGULUS_AERODS_PROGRAM_SIZE,
                EL_REGULUS_AERODS_PROGRAM_SHA256,
            ),
        )
        self.assertEqual(patched_aerods, EL_REGULUS_AERODS_PROGRAM)
        self.assertEqual(patched_aerods.count(bytes.fromhex("13 00")), 0)
        self.assertEqual(patched_aerods.count(bytes.fromhex("3F 00")), 0)
        self.assertEqual(
            patched_aerods.count(bytes.fromhex("14 FD FD 6A 00 00")),
            1,
        )
        patched_entry = _el_regulus_battle_animation_program(patched, 0)
        self.assertEqual(
            (
                len(patched_entry),
                hashlib.sha256(patched_entry).hexdigest(),
            ),
            (
                EL_REGULUS_AERODS_ENTRY_PATCHED_SIZE,
                EL_REGULUS_AERODS_ENTRY_PATCHED_SHA256,
            ),
        )
        self.assertEqual(
            patched_entry[: 4 + len(EL_REGULUS_AERODS_INITIAL_HIDE)],
            bytes.fromhex("0A 00 0C 00") + EL_REGULUS_AERODS_INITIAL_HIDE,
        )

        main_base = EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[0]
        pointer_count = struct.unpack_from("<I", patched, main_base)[0] + 1
        patched_pointers = struct.unpack_from(
            f"<{pointer_count}I",
            patched,
            main_base + 4,
        )
        aerods_pointer_position = (
            main_base + 4 + 4 * (EL_REGULUS_AERODS_ANIMATION_ID + 1)
        )
        self.assertEqual(aerods_pointer_position, 0x138)
        self.assertEqual(
            patched_pointers[EL_REGULUS_AERODS_ANIMATION_ID + 1],
            EL_REGULUS_AERODS_PROGRAM_POINTER,
        )
        cleanup_program = _el_regulus_battle_animation_program(
            patched,
            EL_REGULUS_AERODS_CLEANUP_ANIMATION_ID,
        )
        self.assertEqual(
            (
                EL_REGULUS_AERODS_CLEANUP_ANIMATION_ID,
                EL_REGULUS_AERODS_CLEANUP_ALIAS_ANIMATION_ID,
                EL_REGULUS_AERODS_CLEANUP_PROGRAM_POINTER,
                EL_REGULUS_AERODS_CLEANUP_SOURCE_ALIAS_POINTER,
            ),
            (0x49, 0x4A, 0x7FE4, 0x7FE8),
        )
        self.assertEqual(
            (
                cleanup_program,
                hashlib.sha256(cleanup_program).hexdigest(),
            ),
            (
                bytes.fromhex("06 00 02 00 00 00 77 77"),
                "f94b226189c98d0ab90592a222bbdcdfa7fb13d1e7b9d20ff1b74493390b41d5",
            ),
        )
        self.assertEqual(cleanup_program, EL_REGULUS_AERODS_CLEANUP_PROGRAM)
        self.assertEqual(
            hashlib.sha256(cleanup_program).hexdigest(),
            EL_REGULUS_AERODS_CLEANUP_PROGRAM_SHA256,
        )
        self.assertEqual(
            patched_pointers[EL_REGULUS_AERODS_CLEANUP_ANIMATION_ID + 1],
            EL_REGULUS_AERODS_CLEANUP_PROGRAM_POINTER,
        )
        self.assertEqual(
            patched_pointers[EL_REGULUS_AERODS_CLEANUP_ALIAS_ANIMATION_ID + 1],
            EL_REGULUS_AERODS_SHARED_STUB_POINTER,
        )
        self.assertTrue(
            all(
                patched_pointers[animation_id + 1]
                == EL_REGULUS_AERODS_SHARED_STUB_POINTER
                for animation_id in EL_REGULUS_AERODS_SHARED_STUB_ANIMATION_IDS
            )
        )

        # Stop the complete builder immediately before its final AERODs pass.
        # This independently exposes the audited refaced archive and proves
        # that compaction changes no logical program except the AERODs loader
        # and its dedicated local cleanup animation.
        with patch.object(
            mass_driver,
            "_patch_el_regulus_aerods_animation",
            side_effect=lambda archive: archive,
        ):
            refaced = _patch_el_regulus_battle_entry_animation(source)
        self.assertEqual(
            hashlib.sha256(refaced).hexdigest(),
            EL_REGULUS_BATTLE_ANIMATION_REFACED_SHA256,
        )
        self.assertEqual(len(refaced), len(patched))
        refaced_entry = _el_regulus_battle_animation_program(refaced, 0)
        self.assertEqual(
            (
                len(refaced_entry),
                hashlib.sha256(refaced_entry).hexdigest(),
            ),
            (
                EL_REGULUS_AERODS_ENTRY_SOURCE_SIZE,
                EL_REGULUS_AERODS_ENTRY_SOURCE_SHA256,
            ),
        )
        self.assertEqual(
            patched_entry,
            refaced_entry[:4]
            + EL_REGULUS_AERODS_INITIAL_HIDE
            + refaced_entry[4:],
        )
        refaced_pointer_count = struct.unpack_from("<I", refaced, main_base)[0] + 1
        refaced_pointers = struct.unpack_from(
            f"<{refaced_pointer_count}I",
            refaced,
            main_base + 4,
        )
        for animation_id in range(EL_REGULUS_BATTLE_ANIMATION_COUNT):
            if (
                animation_id in (
                    0,
                    EL_REGULUS_AERODS_ANIMATION_ID,
                    EL_REGULUS_AERODS_CLEANUP_ANIMATION_ID,
                )
                or refaced_pointers[animation_id + 1] == 0
            ):
                continue
            with self.subTest(compacted_animation=animation_id):
                self.assertEqual(
                    _el_regulus_battle_animation_program(refaced, animation_id),
                    _el_regulus_battle_animation_program(patched, animation_id),
                )
        for animation_id in EL_REGULUS_AERODS_SHARED_STUB_ANIMATION_IDS:
            self.assertEqual(
                _el_regulus_battle_animation_program(patched, animation_id),
                EL_REGULUS_AERODS_RETURN_STUB,
            )
        self.assertEqual(
            refaced_pointers[EL_REGULUS_AERODS_CLEANUP_ANIMATION_ID + 1],
            EL_REGULUS_AERODS_CLEANUP_PROGRAM_POINTER,
        )
        self.assertEqual(
            refaced_pointers[EL_REGULUS_AERODS_CLEANUP_ALIAS_ANIMATION_ID + 1],
            EL_REGULUS_AERODS_CLEANUP_SOURCE_ALIAS_POINTER,
        )
        self.assertEqual(
            patched[
                EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1] :
                EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[2]
            ],
            refaced[
                EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1] :
                EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[2]
            ],
        )

        # The loader itself is Vierge's retail, model-independent animation-72
        # wrapper with only the external program selector redirected 0x51->0x6A.
        vierge_main = (
            project / "work" / "_audit_el_regulus_battle" / "2931.bin"
        ).read_bytes()
        retail_loader = _el_regulus_battle_animation_program(
            vierge_main,
            EL_REGULUS_AERODS_ANIMATION_ID,
        )
        self.assertEqual(len(retail_loader), EL_REGULUS_AERODS_PROGRAM_SIZE)
        self.assertEqual(
            {
                index
                for index, (retail, dedicated) in enumerate(
                    zip(retail_loader, patched_aerods, strict=True)
                )
                if retail != dedicated
            },
            {25},
        )
        self.assertEqual(retail_loader[25], EL_REGULUS_AERODS_VIERGE_EXTERNAL_ID)
        self.assertEqual(
            patched_aerods[25],
            EL_REGULUS_AERODS_DEDICATED_EXTERNAL_ID,
        )
        self.assertEqual(
            patched_aerods[12:22],
            bytes.fromhex("04 06 06 00 05 00 5A 08 43 00"),
        )
        self.assertEqual(
            _el_regulus_battle_animation_program(patched, 0x1E),
            bytes.fromhex("06 00 03 00 00 00 77 77"),
        )

        for animation_id in range(1, EL_REGULUS_BATTLE_ANIMATION_COUNT):
            if animation_id in (
                EL_REGULUS_POST_ACTION_ANIMATION_ID,
                EL_REGULUS_AERODS_ANIMATION_ID,
                EL_REGULUS_AERODS_CLEANUP_ANIMATION_ID,
                *EL_REGULUS_ATTACK_ANIMATION_IDS,
                *EL_REGULUS_LEVEL_ONE_DEATHBLOW_ANIMATION_IDS,
                *EL_REGULUS_HIGHER_DEATHBLOW_ANIMATION_IDS,
            ):
                continue
            pointer_position = (
                EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[0]
                + 4
                + 4 * (animation_id + 1)
            )
            relative_start, relative_end = struct.unpack_from(
                "<II", source, pointer_position
            )
            # The retail table deliberately contains null/alias slots.
            if relative_start == 0 or relative_start >= relative_end:
                continue
            with self.subTest(unchanged_animation=animation_id):
                self.assertEqual(
                    _el_regulus_battle_animation_program(source, animation_id),
                    _el_regulus_battle_animation_program(patched, animation_id),
                )
        main_base = EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[0]
        sentinel_position = (
            main_base + 4 + 4 * (EL_REGULUS_BATTLE_ANIMATION_COUNT + 1)
        )
        self.assertEqual(
            struct.unpack_from("<I", patched, sentinel_position)[0],
            EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1] - 0x10,
        )
        pointer_count = struct.unpack_from("<I", patched, main_base)[0] + 1
        pointers = struct.unpack_from(
            f"<{pointer_count}I", patched, main_base + 4
        )
        self.assertTrue(all(pointer % 4 == 0 for pointer in pointers))
        self.assertTrue(
            all(root % 4 == 0 for root in EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS)
        )
        self.assertLess(EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1], 0x8000)

    def test_el_regulus_aerods_external_runs_twelve_real_pods_on_vierge_paths(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        source = (
            project
            / "work"
            / "_audit_aerods_genuine"
            / f"{EL_REGULUS_AERODS_EXTERNAL_CANONICAL_ID}.bin"
        ).read_bytes()
        patched = _patch_el_regulus_aerods_external(source)

        self.assertEqual(
            (
                len(source),
                hashlib.sha256(source).hexdigest(),
                struct.unpack_from("<4I", source, 0),
            ),
            (
                EL_REGULUS_AERODS_EXTERNAL_SOURCE_SIZE,
                EL_REGULUS_AERODS_EXTERNAL_SOURCE_SHA256,
                (2, *EL_REGULUS_AERODS_EXTERNAL_SOURCE_ROOTS),
            ),
        )
        self.assertEqual(
            (
                len(patched),
                hashlib.sha256(patched).hexdigest(),
                struct.unpack_from("<4I", patched, 0),
            ),
            (
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_SIZE,
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_SHA256,
                (2, *EL_REGULUS_AERODS_EXTERNAL_PATCHED_ROOTS),
            ),
        )
        self.assertEqual(
            (
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_SIZE,
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_SHA256,
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_ROOTS,
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_POINTERS[-1],
            ),
            (
                102_280,
                "f3adbfac6c32482460041084fd4736c2fb4e7e3c00a9ef56a384362f3d845e2b",
                (0x10, 0x3E60, 0x18F88),
                0x3E50,
            ),
        )
        self.assertEqual(len(patched) - len(source), 3_332)
        self.assertLessEqual(
            len(patched),
            EL_REGULUS_AERODS_EXTERNAL_SECTOR_CAPACITY,
        )
        self.assertEqual(
            (
                (len(source) + 2047) // 2048,
                (len(patched) + 2047) // 2048,
            ),
            (49, 50),
        )

        main_base, source_asset_start, source_end = (
            EL_REGULUS_AERODS_EXTERNAL_SOURCE_ROOTS
        )
        patched_main_base, patched_asset_start, patched_end = (
            EL_REGULUS_AERODS_EXTERNAL_PATCHED_ROOTS
        )
        self.assertEqual(main_base, patched_main_base)
        self.assertEqual(source_end, len(source))
        self.assertEqual(patched_end, len(patched))
        source_count = struct.unpack_from("<I", source, main_base)[0]
        patched_count = struct.unpack_from("<I", patched, main_base)[0]
        source_pointers = struct.unpack_from(
            f"<{source_count + 1}I",
            source,
            main_base + 4,
        )
        patched_pointers = struct.unpack_from(
            f"<{patched_count + 1}I",
            patched,
            main_base + 4,
        )
        self.assertEqual(
            (source_count, source_pointers),
            (
                EL_REGULUS_AERODS_EXTERNAL_SOURCE_COUNT,
                EL_REGULUS_AERODS_EXTERNAL_SOURCE_POINTERS,
            ),
        )
        self.assertEqual(
            (patched_count, patched_pointers),
            (
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_COUNT,
                EL_REGULUS_AERODS_EXTERNAL_PATCHED_POINTERS,
            ),
        )
        self.assertEqual(
            patched_pointers[: len(source_pointers)],
            tuple(pointer + 52 for pointer in source_pointers),
        )
        source_entries = tuple(
            source[
                main_base + source_pointers[index] :
                main_base + source_pointers[index + 1]
            ]
            for index in range(source_count)
        )
        for index in range(source_count):
            with self.subTest(preserved_external_entry=index):
                self.assertEqual(
                    patched[
                        main_base + patched_pointers[index] :
                        main_base + patched_pointers[index + 1]
                    ],
                    source_entries[index],
                )
        self.assertEqual(
            patched[patched_asset_start:patched_end],
            source[source_asset_start:source_end],
        )

        vierge_index = EL_REGULUS_AERODS_VIERGE_EXTERNAL_ID - 0x50 + 1
        vierge = source_entries[vierge_index]
        self.assertEqual(
            (len(vierge), hashlib.sha256(vierge).hexdigest()),
            (
                EL_REGULUS_AERODS_VIERGE_EXTERNAL_SIZE,
                EL_REGULUS_AERODS_VIERGE_EXTERNAL_SHA256,
            ),
        )
        def remove_audited_spans(
            body: bytes,
            spans: tuple[tuple[int, int, str], ...],
        ) -> bytes:
            cursor = 0
            retained = bytearray()
            for start, end, expected_hash in spans:
                self.assertGreater(end, start)
                self.assertEqual((start % 2, end % 2), (0, 0))
                self.assertEqual(
                    hashlib.sha256(body[start:end]).hexdigest(),
                    expected_hash,
                )
                retained.extend(body[cursor:start])
                cursor = end
            retained.extend(body[cursor:])
            return bytes(retained)

        # All twelve authentic retail trajectories are cloned after the
        # untouched entries. Their audited structural bone selectors are
        # retargeted; complete checked camera packets are then absent from the
        # two camera-owning clones while their native completion callbacks stay.
        for (
            source_id,
            source_bone,
            source_hash,
            selector_offsets,
            trajectory_id,
            target_bone,
            source_size,
            expected_size,
            expected_hash,
            camera_spans,
        ) in zip(
            EL_REGULUS_AERODS_TRAJECTORY_SOURCE_IDS,
            EL_REGULUS_AERODS_TRAJECTORY_SOURCE_BONES,
            EL_REGULUS_AERODS_TRAJECTORY_SOURCE_SHA256,
            EL_REGULUS_AERODS_TRAJECTORY_SELECTOR_OFFSETS,
            EL_REGULUS_AERODS_TRAJECTORY_IDS,
            EL_REGULUS_AERODS_TRAJECTORY_TARGET_BONES,
            EL_REGULUS_AERODS_TRAJECTORY_SOURCE_SIZES,
            EL_REGULUS_AERODS_TRAJECTORY_SIZES,
            EL_REGULUS_AERODS_TRAJECTORY_SHA256,
            EL_REGULUS_AERODS_TRAJECTORY_CAMERA_SPANS,
            strict=True,
        ):
            source_index = source_id - 0x50 + 1
            trajectory_index = trajectory_id - 0x50 + 1
            trajectory_source = source_entries[source_index]
            trajectory = patched[
                main_base + patched_pointers[trajectory_index] :
                main_base + patched_pointers[trajectory_index + 1]
            ]
            with self.subTest(trajectory_id=trajectory_id):
                self.assertEqual(
                    (
                        len(trajectory_source),
                        hashlib.sha256(trajectory_source).hexdigest(),
                        len(trajectory),
                        hashlib.sha256(trajectory).hexdigest(),
                    ),
                    (source_size, source_hash, expected_size, expected_hash),
                )
                remapped = bytearray(trajectory_source)
                for offset in selector_offsets:
                    has_transform_prefix = (
                        trajectory_source[offset - 3 : offset]
                        == bytes.fromhex("04 00 01")
                    )
                    has_controller_prefix = (
                        trajectory_source[offset - 1 : offset] == b"\x1D"
                    )
                    self.assertNotEqual(
                        has_transform_prefix,
                        has_controller_prefix,
                    )
                    self.assertEqual(trajectory_source[offset], source_bone)
                    remapped[offset] = target_bone
                expected_trajectory = remove_audited_spans(
                    bytes(remapped),
                    camera_spans,
                )
                if len(expected_trajectory) % 4:
                    self.assertEqual(source_id, 0x5B)
                    self.assertTrue(
                        expected_trajectory.endswith(
                            bytes.fromhex("16 FF 00 00")
                        )
                    )
                    expected_trajectory += bytes.fromhex("77 77")
                self.assertEqual(trajectory, expected_trajectory)
                for start, end, _expected_hash in camera_spans:
                    self.assertNotIn(bytes(remapped[start:end]), trajectory)
                callback = bytes.fromhex("16 FF 00 00")
                self.assertEqual(trajectory_source.count(callback), 1)
                self.assertEqual(trajectory.count(callback), 1)
                self.assertTrue(
                    trajectory.endswith(
                        (bytes.fromhex("16 FF 00 00"), bytes.fromhex("77 77"))
                    )
                )

        self.assertEqual(
            (
                EL_REGULUS_AERODS_TRAJECTORY_SOURCE_SIZES[8:10],
                EL_REGULUS_AERODS_TRAJECTORY_SIZES[8:10],
                EL_REGULUS_AERODS_TRAJECTORY_SHA256[8:10],
            ),
            (
                (444, 508),
                (304, 364),
                (
                    "f87da4ece26ab7d76d391f7111834a46ef0e9fddb7e63aff824c7a48af78edb0",
                    "4213e6b30b77b2790c66a7bdd13c70a2273d09990bdcf5f02ce3ea085185a55d",
                ),
            ),
        )

        dedicated_index = EL_REGULUS_AERODS_DEDICATED_EXTERNAL_ID - 0x50 + 1
        self.assertEqual(
            (dedicated_index, patched_count, patched_pointers[-1]),
            (27, 28, 0x3E50),
        )
        program = patched[
            main_base + patched_pointers[dedicated_index] :
            main_base + patched_pointers[dedicated_index + 1]
        ]

        # These are Vierge's exact collapsed native pre-launch transforms,
        # retargeted in source-trajectory order to El-Regulus runtime bones.
        # Pin the tuples as well as their encoding so a visually destructive
        # "close enough" fan cannot silently replace the audited pose.
        expected_poses = (
            (0x3D, (1485, 218, 1838), (798, -935, -2464)),
            (0x3E, (1605, 102, -247), (1012, -1345, -2916)),
            (0x3F, (1606, 102, 1801), (1105, -1520, -2756)),
            (0x40, (1772, 106, -281), (947, -1215, -2207)),
            (0x41, (563, 218, 210), (798, -935, 2457)),
            (0x42, (443, 102, -1801), (1013, -1345, 2909)),
            (0x43, (443, 102, 247), (1106, -1520, 2749)),
            (0x44, (276, 106, -1766), (947, -1216, 2201)),
            (0x45, (848, 155, -2006), (-911, -4094, -512)),
            (0x46, (1024, 161, 0), (-639, -4379, -256)),
            (0x47, (1024, 161, -2048), (-639, -4379, 256)),
            (0x48, (1200, 155, -42), (-911, -4094, 512)),
        )
        self.assertEqual(EL_REGULUS_AEROD_COLLAPSED_POSES, expected_poses)
        self.assertEqual(
            EL_REGULUS_AEROD_CHILD_TRANSLATIONS,
            tuple(
                (bone, *translation)
                for bone, _rotation, translation in expected_poses
            ),
        )
        pose_seed = b"".join(
            struct.pack(
                "<BBH3h",
                0x62,
                mode,
                bone,
                *(rotation if mode == 0 else translation),
            )
            for bone, rotation, translation in expected_poses
            for mode in (0, 1)
        )
        self.assertEqual(
            (
                len(pose_seed),
                hashlib.sha256(pose_seed).hexdigest(),
                EL_REGULUS_AEROD_POSE_SEED_SIZE,
                EL_REGULUS_AEROD_POSE_SEED_SHA256,
            ),
            (
                240,
                "58692eb99ed5c4c3e02bc6a7eae73d83d708db501b1708cdcdf84b68e56c631f",
                240,
                "58692eb99ed5c4c3e02bc6a7eae73d83d708db501b1708cdcdf84b68e56c631f",
            ),
        )
        for pose_index, (bone, rotation, translation) in enumerate(
            expected_poses
        ):
            pose_offset = pose_index * 20
            self.assertEqual(
                struct.unpack_from("<BBH3h", pose_seed, pose_offset),
                (0x62, 0, bone, *rotation),
            )
            self.assertEqual(
                struct.unpack_from("<BBH3h", pose_seed, pose_offset + 10),
                (0x62, 1, bone, *translation),
            )

        reset = bytes.fromhex("0A 00 0C 00")
        hide_gate = bytes((0x23, 0x80, EL_REGULUS_AEROD_GATE_BONE, 0x00))
        show_gate = bytes((0x23, 0x01, EL_REGULUS_AEROD_GATE_BONE, 0x00))
        hide_pods = b"".join(
            bytes((0x23, 0x00, bone, 0x00))
            for bone in EL_REGULUS_AEROD_VISIBLE_BONES
        )
        wave_trajectories = (
            bytes.fromhex(
                "23 01 40 00 15 61 40 00 23 01 44 00 15 65 44 00 "
                "01 00 02 00 01 00 04 00"
            )
            + bytes.fromhex(
                "23 01 3F 00 15 60 3F 00 23 01 43 00 15 64 43 00 "
                "01 00 02 00 01 00 02 00"
            )
            + bytes.fromhex(
                "23 01 3E 00 15 5F 3E 00 23 01 42 00 15 63 42 00 "
                "01 00 02 00 01 00 02 00"
            )
            + bytes.fromhex(
                "23 01 3D 00 15 5E 3D 00 23 01 41 00 15 62 41 00 "
                "01 00 02 00 01 00 02 00"
            )
        )
        lead_trajectories = (
            bytes.fromhex("23 01 45 00 15 66 45 00 01 00 04 00")
            + bytes.fromhex("23 01 46 00 15 67 46 00 01 00 04 00")
            + bytes.fromhex("23 01 47 00 15 68 47 00 01 00 04 00")
            + bytes.fromhex("23 01 48 00 15 69 48 00 01 00 08 00")
        )
        camera_start, camera_end = EL_REGULUS_AERODS_EXTERNAL_CAMERA_SLICE
        launch_start, launch_end = EL_REGULUS_AERODS_EXTERNAL_LAUNCH_SLICE
        damage_start, damage_end = EL_REGULUS_AERODS_EXTERNAL_DAMAGE_SLICE
        pose_settle = EL_REGULUS_AERODS_POSE_SETTLE
        owner_motion = EL_REGULUS_AERODS_OWNER_MOTION
        camera_source = vierge[camera_start:camera_end]
        launch_source = vierge[launch_start:launch_end]
        camera_segment = remove_audited_spans(
            camera_source,
            EL_REGULUS_AERODS_EXTERNAL_CAMERA_SPANS,
        )
        launch_segment = remove_audited_spans(
            launch_source,
            EL_REGULUS_AERODS_EXTERNAL_LAUNCH_CAMERA_SPANS,
        )
        self.assertEqual(pose_settle, bytes.fromhex("01 00 01 00"))
        self.assertEqual(
            (
                len(owner_motion),
                hashlib.sha256(owner_motion).hexdigest(),
                owner_motion,
            ),
            (
                22,
                EL_REGULUS_AERODS_OWNER_MOTION_SHA256,
                bytes.fromhex(
                    "13 00 03 00 00 04 21 00 11 03 00 00 21 00 "
                    "13 00 10 00 00 04 21 00"
                ),
            ),
        )
        self.assertEqual(camera_segment, bytes.fromhex("01 00 0E 00"))
        self.assertEqual(
            (len(launch_segment), hashlib.sha256(launch_segment).hexdigest()),
            (
                70,
                "f1aa0afb6e526af1599ca77bae816d3c244bc95d54f52ad1ab2c7e920d4fc725",
            ),
        )
        for start, end, _expected_hash in EL_REGULUS_AERODS_EXTERNAL_CAMERA_SPANS:
            self.assertNotIn(camera_source[start:end], camera_segment)
            self.assertNotIn(camera_source[start:end], program)
        for (
            start,
            end,
            _expected_hash,
        ) in EL_REGULUS_AERODS_EXTERNAL_LAUNCH_CAMERA_SPANS:
            self.assertNotIn(launch_source[start:end], launch_segment)
            self.assertNotIn(launch_source[start:end], program)
        expected_program = (
            reset
            + hide_gate
            + pose_seed
            + pose_settle
            + owner_motion
            + show_gate
            + wave_trajectories
            + camera_segment
            + lead_trajectories
            + launch_segment
            + vierge[damage_start:damage_end]
            + hide_pods
            + hide_gate
            + EL_REGULUS_AERODS_EXTERNAL_COMPLETION
            + bytes.fromhex("77 77 77 77")
        )
        self.assertEqual(program, expected_program)
        self.assertEqual(
            (
                len(program),
                hashlib.sha256(program).hexdigest(),
                EL_REGULUS_AERODS_DEDICATED_EXTERNAL_PROGRAM_SIZE,
                EL_REGULUS_AERODS_DEDICATED_EXTERNAL_PROGRAM_SHA256,
            ),
            (
                572,
                "ff297ca369bc1e102ebdd0af44e9878c7658ccdbe19e5c4349b903cf6df34d31",
                572,
                "ff297ca369bc1e102ebdd0af44e9878c7658ccdbe19e5c4349b903cf6df34d31",
            ),
        )

        # Reset and recursively hide the whole gate before writing each pod's
        # absolute rotation then absolute translation. At +0xF8, wait one
        # deterministic tick for the dirty matrices to compose while hidden.
        # El-Regulus then performs a model-local keyframe-3/keyframe-0x10
        # launch motion before any pod is revealed or trajectory starts.
        pose_seed_offset = len(reset) + len(hide_gate)
        pose_seed_end = pose_seed_offset + len(pose_seed)
        pose_settle_end = pose_seed_end + len(pose_settle)
        owner_motion_end = pose_settle_end + len(owner_motion)
        self.assertEqual(pose_seed_end, 0xF8)
        self.assertTrue(
            program.startswith(
                reset
                + hide_gate
                + pose_seed
                + pose_settle
                + owner_motion
                + show_gate
            )
        )
        self.assertEqual(program.index(pose_seed), pose_seed_offset)
        self.assertEqual(program[0xF8:0xFC], pose_settle)
        self.assertEqual(program.index(owner_motion), pose_settle_end)
        self.assertEqual((pose_settle_end, owner_motion_end), (0xFC, 0x112))
        self.assertEqual(program.index(show_gate), owner_motion_end)
        self.assertEqual(program.count(owner_motion), 1)
        self.assertNotIn(bytes.fromhex("23 81 3C 00"), program)

        launch_order = (
            (0x61, 0x40),
            (0x65, 0x44),
            (0x60, 0x3F),
            (0x64, 0x43),
            (0x5F, 0x3E),
            (0x63, 0x42),
            (0x5E, 0x3D),
            (0x62, 0x41),
            (0x66, 0x45),
            (0x67, 0x46),
            (0x68, 0x47),
            (0x69, 0x48),
        )
        launch_offsets = []
        for trajectory_id, target_bone in launch_order:
            show_and_call = bytes(
                (
                    0x23,
                    0x01,
                    target_bone,
                    0x00,
                    0x15,
                    trajectory_id,
                    target_bone,
                    0x00,
                )
            )
            self.assertEqual(program.count(show_and_call), 1)
            launch_offsets.append(program.index(show_and_call))
        self.assertEqual(launch_offsets, sorted(launch_offsets))
        self.assertEqual(min(launch_offsets), 0x116)
        self.assertEqual(
            min(
                program.index(bytes((0x15, trajectory_id, target_bone, 0x00)))
                for trajectory_id, target_bone in launch_order
            ),
            0x11A,
        )
        self.assertGreater(min(launch_offsets), owner_motion_end)

        # Twelve direct solid meshes follow their individual Vierge paths.
        # Damage dispatches exactly once, then every pod and the recursive gate
        # are hidden before the checked direct opcode-2 completion runs while
        # the controller pointer is still live.
        self.assertEqual(program.count(hide_gate), 2)
        self.assertEqual(program.count(show_gate), 1)
        self.assertEqual(program.count(pose_seed), 1)
        for trajectory_id, target_bone in zip(
            EL_REGULUS_AERODS_TRAJECTORY_IDS,
            EL_REGULUS_AERODS_TRAJECTORY_TARGET_BONES,
            strict=True,
        ):
            self.assertEqual(
                program.count(bytes((0x15, trajectory_id, target_bone, 0x00))),
                1,
            )
            self.assertEqual(
                program.count(bytes((0x23, 0x01, target_bone, 0x00))),
                1,
            )
            self.assertEqual(
                program.count(bytes((0x23, 0x00, target_bone, 0x00))),
                1,
            )
        damage_offset = (
            len(reset)
            + len(hide_gate)
            + len(pose_seed)
            + len(pose_settle)
            + len(owner_motion)
            + len(show_gate)
            + len(wave_trajectories)
            + len(camera_segment)
            + len(lead_trajectories)
            + len(launch_segment)
        )
        self.assertEqual(damage_offset, 0x1F0)
        self.assertEqual(
            program[damage_offset : damage_offset + 2],
            bytes.fromhex("3F 00"),
        )
        self.assertEqual(program.count(bytes.fromhex("2F 00")), 1)
        self.assertEqual(program.count(EL_REGULUS_AERODS_EXTERNAL_COMPLETION), 1)
        self.assertEqual(
            program.index(EL_REGULUS_AERODS_EXTERNAL_COMPLETION),
            0x226,
        )
        self.assertEqual(
            hashlib.sha256(EL_REGULUS_AERODS_EXTERNAL_COMPLETION).hexdigest(),
            "129057ff034a7b8037ebf9b698979e3b4bc38915d8185abc3c65257b7e012279",
        )
        self.assertTrue(
            EL_REGULUS_AERODS_EXTERNAL_COMPLETION.endswith(
                bytes.fromhex("2F 00 02 00 00 00")
            )
        )
        self.assertNotIn(bytes.fromhex("14 FD FD 49 00 00"), program)
        self.assertNotIn(bytes.fromhex("14 FD FD 1E 00 00"), program)
        for forbidden in (
            bytes.fromhex("13 00 40 00"),
            bytes.fromhex("13 00 41 00"),
            bytes.fromhex("13 00 42 00"),
            bytes.fromhex("13 00 43 00"),
            bytes.fromhex("13 00 44 00"),
            bytes.fromhex("13 00 45 00"),
            bytes.fromhex("13 00 46 00"),
        ):
            self.assertNotIn(forbidden, program)
        self.assertEqual(
            program[damage_offset:],
            vierge[damage_start:damage_end]
            + hide_pods
            + hide_gate
            + EL_REGULUS_AERODS_EXTERNAL_COMPLETION
            + bytes.fromhex("77 77 77 77"),
        )

    def test_el_regulus_level_one_deathblows_dispatch_damage(self) -> None:
        project = REPOSITORY_ROOT
        source = (
            project
            / "work"
            / "_audit_el_regulus_battle"
            / f"{EL_REGULUS_BATTLE_ANIMATION_CANONICAL_ID}.bin"
        ).read_bytes()
        patched = _patch_el_regulus_battle_entry_animation(source)
        damage_dispatch = bytes.fromhex("3F 00")
        completion = bytes.fromhex("2F 00 02 00 00 00")
        padding = bytes.fromhex("77 77")

        for (
            animation_id,
            source_size,
            source_hash,
            damage_offset,
            padding_adjustment,
            patched_size,
            patched_hash,
        ) in zip(
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_ANIMATION_IDS,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_SOURCE_SIZES,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_SOURCE_SHA256,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_DAMAGE_OFFSETS,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_PADDING_ADJUSTMENTS,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_PATCHED_SIZES,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_PATCHED_SHA256,
            strict=True,
        ):
            with self.subTest(animation_id=animation_id):
                source_program = _el_regulus_battle_animation_program(
                    source, animation_id
                )
                patched_program = _el_regulus_battle_animation_program(
                    patched, animation_id
                )
                self.assertEqual(len(source_program), source_size)
                self.assertEqual(
                    hashlib.sha256(source_program).hexdigest(),
                    source_hash,
                )
                self.assertEqual(source_program.count(damage_dispatch), 0)
                self.assertEqual(len(patched_program), patched_size)
                self.assertEqual(
                    hashlib.sha256(patched_program).hexdigest(),
                    patched_hash,
                )
                self.assertEqual(patched_program.count(damage_dispatch), 1)

                if animation_id == EL_REGULUS_DOUBLE_IMPACT_ANIMATION_ID:
                    motion = bytes.fromhex(
                        "13 00 40 00 00 02 21 00 "
                        "11 40 00 00 21 00"
                    )
                    self.assertTrue(
                        patched_program.startswith(
                            bytes.fromhex(
                                "05 00 0A 00 0C 00 58 FF 43 01"
                            )
                        )
                    )
                    self.assertEqual(patched_program.count(motion), 2)
                    first_motion = patched_program.index(motion)
                    second_motion = patched_program.index(
                        motion, first_motion + len(motion)
                    )
                    self.assertLess(
                        second_motion,
                        patched_program.index(damage_dispatch),
                    )
                    self.assertEqual(
                        patched_program[
                            first_motion + len(motion) : second_motion
                        ],
                        bytes.fromhex("01 00 0A 00"),
                    )
                    self.assertTrue(
                        patched_program.endswith(completion + padding)
                    )
                elif animation_id == EL_REGULUS_ETHER_BEAM_ANIMATION_ID:
                    self.assertGreater(len(patched_program), len(source_program))
                    self.assertTrue(
                        patched_program.startswith(
                            bytes.fromhex(
                                "05 00 0A 00 0C 00 58 FF 43 01"
                            )
                        )
                    )
                    self.assertEqual(
                        patched_program.count(EL_REGULUS_BEAM_SOUND_PACKET),
                        1,
                    )
                    self.assertEqual(
                        patched_program.count(EL_REGULUS_NATIVE_BEAM_PACKET),
                        1,
                    )
                    self.assertIn(bytes.fromhex("01 00 1E 00"), patched_program)
                    self.assertIn(bytes.fromhex("01 00 3C 00"), patched_program)
                    self.assertLess(
                        patched_program.index(EL_REGULUS_BEAM_SOUND_PACKET),
                        patched_program.index(EL_REGULUS_NATIVE_BEAM_PACKET),
                    )
                    sound_end = (
                        patched_program.index(EL_REGULUS_BEAM_SOUND_PACKET)
                        + len(EL_REGULUS_BEAM_SOUND_PACKET)
                    )
                    self.assertEqual(
                        patched_program[
                            sound_end :
                            sound_end + 4
                        ],
                        struct.pack(
                            "<HH",
                            1,
                            EL_REGULUS_BEAM_SOUND_DISPATCH_DELAY_TICKS,
                        ),
                    )
                    self.assertTrue(
                        patched_program.endswith(completion + padding)
                    )
                elif animation_id == EL_REGULUS_BEAT_STORM_ANIMATION_ID:
                    self.assertEqual(EL_REGULUS_BEAT_STORM_CLIPS, (0x40, 0x41))
                    self.assertTrue(
                        patched_program.startswith(
                            bytes.fromhex("05 00 0A 00 0C 00")
                        )
                    )
                    motions = tuple(
                        bytes(
                            (
                                0x13,
                                0x00,
                                clip,
                                0x00,
                                0x00,
                                0x02,
                                0x21,
                                0x00,
                                0x11,
                                clip,
                                0x00,
                                0x00,
                                0x21,
                                0x00,
                            )
                        )
                        for clip in EL_REGULUS_BEAT_STORM_CLIPS
                    )
                    self.assertEqual(
                        tuple(patched_program.count(motion) for motion in motions),
                        (1, 1),
                    )
                    first_motion = patched_program.index(motions[0])
                    second_motion = patched_program.index(motions[1])
                    damage = patched_program.index(damage_dispatch)
                    self.assertLess(first_motion, second_motion)
                    self.assertLess(second_motion, damage)
                    for forbidden_clip in (0x43, 0x44, 0x45):
                        self.assertNotIn(
                            bytes((0x13, 0x00, forbidden_clip, 0x00)),
                            patched_program,
                        )
                    self.assertTrue(
                        patched_program.endswith(completion + padding)
                    )
                else:
                    self.fail(f"unexpected Level-1 animation {animation_id}")

        main_base = EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[0]
        pointers = struct.unpack_from(
            f"<{EL_REGULUS_BATTLE_ANIMATION_COUNT + 2}I",
            patched,
            main_base + 4,
        )
        self.assertTrue(all(pointer % 4 == 0 for pointer in pointers))
        self.assertEqual(
            pointers[36:41],
            (0x7824, 0x7864, 0x790C, 0x7938, 0x79B8),
        )

        source_model_start = EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[1]
        patched_model_start = EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1]
        source_container = source[
            source_model_start : EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[2]
        ]
        patched_container = patched[
            patched_model_start : EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[2]
        ]
        self.assertEqual(patched_container, source_container)

    def test_el_regulus_ether_beam_sound_uses_audited_auxiliary_preload(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        audit_root = project / "work" / "_audit_el_regulus_battle"
        source = (
            audit_root / f"{EL_REGULUS_BEAM_SOUND_AUX_CANONICAL_ID}.bin"
        ).read_bytes()
        donor = (
            audit_root / f"{EL_REGULUS_BEAM_SOUND_DONOR_CANONICAL_ID}.bin"
        ).read_bytes()
        xenogears_donor = (
            project
            / "work"
            / "_audit_el_regulus_beam_audio"
            / f"{EL_REGULUS_BEAM_SOUND_XENOGEARS_CANONICAL_ID}.bin"
        ).read_bytes()
        common_wds = (
            audit_root
            / f"{EL_REGULUS_BEAM_SOUND_COMMON_WDS_CANONICAL_ID}.bin"
        ).read_bytes()
        patched = _patch_el_regulus_aux_beam_sound(
            source, donor, xenogears_donor, common_wds
        )

        self.assertEqual(len(source), EL_REGULUS_BEAM_SOUND_AUX_SOURCE_SIZE)
        self.assertEqual(
            hashlib.sha256(source).hexdigest(),
            EL_REGULUS_BEAM_SOUND_AUX_SOURCE_SHA256,
        )
        self.assertEqual(
            struct.unpack_from("<4I", source, 0),
            (2, *EL_REGULUS_BEAM_SOUND_AUX_SOURCE_ROOTS),
        )
        self.assertEqual(len(patched), EL_REGULUS_BEAM_SOUND_AUX_PATCHED_SIZE)
        self.assertEqual(
            hashlib.sha256(patched).hexdigest(),
            EL_REGULUS_BEAM_SOUND_AUX_PATCHED_SHA256,
        )
        self.assertEqual(
            struct.unpack_from("<4I", patched, 0),
            (2, *EL_REGULUS_BEAM_SOUND_AUX_PATCHED_ROOTS),
        )

        source_bank_start = EL_REGULUS_BEAM_SOUND_AUX_SOURCE_ROOTS[1]
        patched_bank_start = EL_REGULUS_BEAM_SOUND_AUX_PATCHED_ROOTS[1]
        source_bank = source[source_bank_start:]
        patched_bank = patched[patched_bank_start:]
        self.assertEqual(
            len(source_bank),
            EL_REGULUS_BEAM_SOUND_AUX_SOURCE_CONTAINER_END,
        )
        self.assertEqual(
            len(patched_bank),
            EL_REGULUS_BEAM_SOUND_AUX_PATCHED_CONTAINER_END,
        )
        self.assertEqual(
            hashlib.sha256(patched_bank).hexdigest(),
            EL_REGULUS_BEAM_SOUND_AUX_PATCHED_CONTAINER_SHA256,
        )
        self.assertEqual(
            struct.unpack_from("<I", patched_bank, 0)[0],
            EL_REGULUS_BEAM_SOUND_AUX_CONTAINER_COUNT,
        )
        self.assertEqual(
            struct.unpack_from(
                f"<{EL_REGULUS_BEAM_SOUND_AUX_CONTAINER_COUNT + 1}I",
                patched_bank,
                4,
            ),
            EL_REGULUS_BEAM_SOUND_AUX_PATCHED_POINTERS,
        )

        donor_start, donor_end = EL_REGULUS_BEAM_SOUND_DONOR_SEDS_BOUNDS
        donor_seds = donor[donor_start:donor_end]
        fire_start, fire_end = EL_REGULUS_BEAM_SOUND_DONOR_FIRE_BOUNDS
        wds_start, wds_end = EL_REGULUS_BEAM_SOUND_DONOR_WDS_BOUNDS
        donor_wds = donor[wds_start:wds_end]
        xenogears_start, xenogears_end = (
            EL_REGULUS_BEAM_SOUND_XENOGEARS_SEDS_BOUNDS
        )
        xenogears_seds = xenogears_donor[
            xenogears_start:xenogears_end
        ]
        xenogears_effect_start, xenogears_effect_end = (
            EL_REGULUS_BEAM_SOUND_XENOGEARS_EFFECT_BOUNDS
        )
        composite_seds = _build_el_regulus_beam_sound_seds(
            donor_seds,
            xenogears_seds,
        )
        self.assertEqual(
            hashlib.sha256(donor).hexdigest(),
            EL_REGULUS_BEAM_SOUND_DONOR_FILE_SHA256,
        )
        self.assertEqual(
            hashlib.sha256(donor_seds).hexdigest(),
            EL_REGULUS_BEAM_SOUND_DONOR_SEDS_SHA256,
        )
        self.assertEqual(_sound_file_checksum(donor_seds), 0)
        self.assertEqual(
            hashlib.sha256(donor_seds[fire_start:fire_end]).hexdigest(),
            EL_REGULUS_BEAM_SOUND_DONOR_FIRE_SHA256,
        )
        self.assertEqual(len(common_wds), EL_REGULUS_BEAM_SOUND_COMMON_WDS_SIZE)
        self.assertEqual(
            hashlib.sha256(common_wds).hexdigest(),
            EL_REGULUS_BEAM_SOUND_COMMON_WDS_SHA256,
        )
        self.assertEqual(
            hashlib.sha256(donor_wds).hexdigest(),
            EL_REGULUS_BEAM_SOUND_DONOR_WDS_SHA256,
        )
        self.assertEqual(donor_wds, common_wds)
        self.assertEqual(
            len(xenogears_donor),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_FILE_SIZE,
        )
        self.assertEqual(
            hashlib.sha256(xenogears_donor).hexdigest(),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_FILE_SHA256,
        )
        self.assertEqual(
            hashlib.sha256(xenogears_seds).hexdigest(),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_SEDS_SHA256,
        )
        self.assertEqual(_sound_file_checksum(xenogears_seds), 0)
        self.assertEqual(
            tuple(
                struct.unpack_from("<34H", xenogears_seds, 0x20)[
                    index
                ]
                for index in (14, 15, 16, 17, 18)
            ),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_EFFECT_POINTERS,
        )
        self.assertEqual(
            hashlib.sha256(
                xenogears_seds[
                    xenogears_effect_start:xenogears_effect_end
                ]
            ).hexdigest(),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_EFFECT_SHA256,
        )
        xenogears_program = _el_regulus_battle_animation_program(
            xenogears_donor,
            EL_REGULUS_BEAM_SOUND_XENOGEARS_ANIMATION_ID,
        )
        self.assertEqual(
            len(xenogears_program),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_ANIMATION_SIZE,
        )
        self.assertEqual(
            hashlib.sha256(xenogears_program).hexdigest(),
            EL_REGULUS_BEAM_SOUND_XENOGEARS_ANIMATION_SHA256,
        )
        self.assertEqual(
            xenogears_program.count(
                EL_REGULUS_BEAM_SOUND_XENOGEARS_SOURCE_PACKET
            ),
            1,
        )

        self.assertEqual(
            len(composite_seds),
            EL_REGULUS_BEAM_SOUND_COMPOSITE_SEDS_SIZE,
        )
        self.assertEqual(
            hashlib.sha256(composite_seds).hexdigest(),
            EL_REGULUS_BEAM_SOUND_COMPOSITE_SEDS_SHA256,
        )
        self.assertEqual(_sound_file_checksum(composite_seds), 0)
        self.assertEqual(
            struct.unpack_from("<H", composite_seds, 0x12)[0],
            EL_REGULUS_BEAM_SOUND_COMPOSITE_EFFECT_COUNT,
        )
        self.assertEqual(
            struct.unpack_from("<I", composite_seds, 0x18)[0],
            EL_REGULUS_BEAM_SOUND_COMPOSITE_DATA_OFFSET,
        )
        self.assertEqual(
            struct.unpack_from(
                f"<{EL_REGULUS_BEAM_SOUND_COMPOSITE_EFFECT_COUNT * 2}H",
                composite_seds,
                0x20,
            ),
            EL_REGULUS_BEAM_SOUND_COMPOSITE_POINTERS,
        )
        self.assertEqual(
            composite_seds[0x44:0x19A],
            donor_seds[0x3C:0x192],
        )
        self.assertEqual(
            composite_seds[0x19A:],
            xenogears_seds[
                xenogears_effect_start:xenogears_effect_end
            ],
        )
        self.assertEqual(patched_bank[0x20:], composite_seds)
        self.assertEqual(patched[:12], source[:12])
        self.assertEqual(
            patched[16:patched_bank_start],
            source[16:source_bank_start],
        )

        self.assertEqual(
            EL_REGULUS_BEAM_SOUND_PACKET,
            bytes.fromhex(
                "63 01 0C 00 00 00 05 07 00 02 08 00"
            ),
        )
        self.assertEqual(
            EL_REGULUS_GUIDED_SHOT_SOUND_PACKET,
            bytes.fromhex(
                "63 01 0C 00 00 00 05 04 00 02 05 00"
            ),
        )

        el_regulus = (
            audit_root / f"{EL_REGULUS_BATTLE_ANIMATION_CANONICAL_ID}.bin"
        ).read_bytes()
        self.assertEqual(
            _el_regulus_battle_animation_program(el_regulus, 29),
            bytes.fromhex("04 01 05 00 05 00 03 00 00 00 77 77"),
        )

    def test_el_regulus_higher_deathblows_replace_every_retail_stub(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        source = (
            project
            / "work"
            / "_audit_el_regulus_battle"
            / f"{EL_REGULUS_BATTLE_ANIMATION_CANONICAL_ID}.bin"
        ).read_bytes()
        patched = _patch_el_regulus_battle_entry_animation(source)
        stub = bytes.fromhex("02 00 00 00")
        damage_dispatch = bytes.fromhex("3F 00")
        completion = bytes.fromhex("2F 00 02 00 00 00")
        offensive_clips = tuple(
            bytes((0x13, 0x00, clip, 0x00))
            for clip in range(0x40, 0x43)
        )
        collapse_clip = bytes.fromhex("13 00 45 00")

        self.assertEqual(
            EL_REGULUS_HIGHER_DEATHBLOW_CLIP_SEQUENCES,
            (
                (0x40, 0x41),
                (0x41,),
                (0x42, 0x40),
                (0x40, 0x41, 0x40),
                (0x41, 0x41),
                (0x42, 0x40, 0x42),
                (0x40, 0x41),
                (0x41, 0x42),
                (0x42, 0x40),
            ),
        )

        for animation_id, expected_clips, expected_size, expected_hash in zip(
            EL_REGULUS_HIGHER_DEATHBLOW_ANIMATION_IDS,
            EL_REGULUS_HIGHER_DEATHBLOW_CLIP_SEQUENCES,
            EL_REGULUS_HIGHER_DEATHBLOW_PATCHED_SIZES,
            EL_REGULUS_HIGHER_DEATHBLOW_PATCHED_SHA256,
            strict=True,
        ):
            with self.subTest(animation_id=animation_id):
                self.assertEqual(
                    _el_regulus_battle_animation_program(
                        source, animation_id
                    ),
                    stub,
                )
                program = _el_regulus_battle_animation_program(
                    patched, animation_id
                )
                self.assertEqual(len(program), expected_size)
                self.assertEqual(
                    hashlib.sha256(program).hexdigest(), expected_hash
                )
                self.assertEqual(program.count(damage_dispatch), 1)
                self.assertEqual(program.count(completion), 1)
                self.assertTrue(any(clip in program for clip in offensive_clips))
                self.assertNotIn(collapse_clip, program)
                signatures = tuple(
                    bytes((0x13, 0x00, clip, 0x00))
                    for clip in expected_clips
                )
                for clip, signature in zip(
                    range(0x40, 0x43),
                    offensive_clips,
                    strict=True,
                ):
                    self.assertEqual(
                        program.count(signature),
                        expected_clips.count(clip),
                    )
                positions = []
                cursor = 0
                for signature in signatures:
                    position = program.index(signature, cursor)
                    positions.append(position)
                    cursor = position + len(signature)
                self.assertEqual(tuple(positions), tuple(sorted(positions)))

        guided_beams = (39, 42, 68)
        raimai_beams = (69, 70)
        for animation_id in (*guided_beams, *raimai_beams):
            with self.subTest(beam_animation=animation_id):
                program = _el_regulus_battle_animation_program(
                    patched, animation_id
                )
                self.assertEqual(
                    program.count(EL_REGULUS_NATIVE_BEAM_PACKET), 1
                )
                expected_sound = (
                    EL_REGULUS_GUIDED_SHOT_SOUND_PACKET
                    if animation_id in guided_beams
                    else EL_REGULUS_BEAM_SOUND_PACKET
                )
                unexpected_sound = (
                    EL_REGULUS_BEAM_SOUND_PACKET
                    if animation_id in guided_beams
                    else EL_REGULUS_GUIDED_SHOT_SOUND_PACKET
                )
                self.assertEqual(program.count(expected_sound), 1)
                self.assertNotIn(unexpected_sound, program)

        infinity_melee_clips = dict(
            zip(
                EL_REGULUS_HIGHER_DEATHBLOW_ANIMATION_IDS[-3:],
                EL_REGULUS_HIGHER_DEATHBLOW_CLIP_SEQUENCES[-3:],
                strict=True,
            )
        )
        for animation_id, clips in infinity_melee_clips.items():
            program = _el_regulus_battle_animation_program(
                patched, animation_id
            )
            with self.subTest(infinity_animation=animation_id):
                positions = tuple(
                    program.index(bytes((0x13, 0x00, clip, 0x00)))
                    for clip in clips
                )
                beam_position = program.index(EL_REGULUS_NATIVE_BEAM_PACKET)
                self.assertEqual(positions, tuple(sorted(positions)))
                self.assertLess(positions[-1], beam_position)
                self.assertEqual(program.count(damage_dispatch), 1)

        self.assertEqual(
            EL_REGULUS_HIGHER_DEATHBLOW_POWERS[-3:],
            (50, 55, 60),
        )
        self.assertEqual(
            EL_REGULUS_HIGHER_DEATHBLOW_FUEL_COSTS[-3:],
            (10, 20, 30),
        )

        model_start = EL_REGULUS_BATTLE_ARCHIVE_PATCHED_ROOTS[1]
        source_model_start = EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[1]
        source_container = source[
            source_model_start : EL_REGULUS_BATTLE_ARCHIVE_SOURCE_ROOTS[2]
        ]
        self.assertEqual(
            patched[model_start:],
            source_container,
        )
        self.assertLess(model_start, 0x8000)

