    def test_el_regulus_bootstrap_uses_retail_attack_level_accessories(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        source = (
            project
            / "work"
            / "_audit_el_regulus_damage"
            / f"{EL_REGULUS_ATTACK_STATS_CANONICAL_ID}.bin"
        ).read_bytes()
        archive_count = struct.unpack_from("<I", source, 0)[0]
        offsets = struct.unpack_from(f"<{archive_count}I", source, 4)
        _validate_el_regulus_attack_level_accessories(source, offsets)

        entry = EL_REGULUS_GEAR_ACCESSORY_DATA_ARCHIVE_ENTRY
        decoded, _ = _decode_lzss_complete_groups(
            source[offsets[entry] : offsets[entry + 1]]
        )

        def effect(item_id: int) -> bytes:
            start = item_id * EL_REGULUS_GEAR_ACCESSORY_RECORD_SIZE
            effect_start = start + EL_REGULUS_GEAR_ACCESSORY_EFFECT_OFFSET
            effect_end = start + EL_REGULUS_GEAR_ACCESSORY_RECORD_SIZE
            return decoded[effect_start:effect_end]

        self.assertEqual(
            tuple(
                effect(item_id)
                for item_id in EL_REGULUS_FRAME_HP_ACCESSORY_IDS
            ),
            EL_REGULUS_FRAME_HP_EFFECT_SIGNATURES,
        )
        self.assertEqual(
            tuple(
                effect(item_id)
                for item_id in EL_REGULUS_ATTACK_LEVEL_MAX_ACCESSORY_IDS
            ),
            EL_REGULUS_ATTACK_LEVEL_MAX_EFFECT_SIGNATURES,
        )
        self.assertEqual(
            EL_REGULUS_ATTACK_LEVEL_MAX_ACCESSORY_IDS,
            (0x60, 0x61, 0x62),
        )
        self.assertNotEqual(
            EL_REGULUS_FRAME_HP_EFFECT_SIGNATURES,
            EL_REGULUS_ATTACK_LEVEL_MAX_EFFECT_SIGNATURES,
        )

    def test_el_regulus_standard_attack_balance_is_isolated(self) -> None:
        project = REPOSITORY_ROOT
        source = (
            project
            / "work"
            / "_audit_el_regulus_damage"
            / f"{EL_REGULUS_ATTACK_STATS_CANONICAL_ID}.bin"
        ).read_bytes()
        patched = _patch_el_regulus_attack_balance(source)
        self.assertEqual(EL_REGULUS_ATTACK_STATS_CANONICAL_ID, 2594)
        count = struct.unpack_from("<I", source, 0)[0]
        offsets = struct.unpack_from(f"<{count}I", source, 4)
        entry = EL_REGULUS_ATTACK_STATS_ARCHIVE_ENTRY
        start, end = offsets[entry], offsets[entry + 1]
        source_decoded, source_consumed = _decode_lzss_complete_groups(
            source[start:end] + bytes(16)
        )
        patched_decoded, consumed = _decode_lzss_complete_groups(
            patched[start:end]
        )

        self.assertEqual(count, EL_REGULUS_ATTACK_STATS_ARCHIVE_COUNT)
        self.assertEqual(entry, 22 + EL_REGULUS_GEAR_ID)
        self.assertEqual(
            (entry, start, end),
            (32, *EL_REGULUS_ATTACK_STATS_ENTRY_RANGE),
        )
        self.assertEqual(
            (
                end - start,
                hashlib.sha256(source[start:end]).hexdigest(),
                source_consumed,
            ),
            (
                EL_REGULUS_ATTACK_STATS_PACKED_PATCHED_SIZE,
                EL_REGULUS_ATTACK_STATS_ENTRY_SOURCE_SHA256,
                EL_REGULUS_ATTACK_STATS_ENTRY_RUNTIME_CONSUMED,
            ),
        )
        self.assertEqual(
            hashlib.sha256(source).hexdigest(),
            EL_REGULUS_ATTACK_STATS_SOURCE_SHA256,
        )
        self.assertEqual(
            hashlib.sha256(patched).hexdigest(),
            EL_REGULUS_ATTACK_STATS_PATCHED_SHA256,
        )
        self.assertEqual(source[:start], patched[:start])
        self.assertEqual(source[end:], patched[end:])
        self.assertLessEqual(consumed, end - start)
        self.assertEqual(
            (
                len(patched[start:end]),
                hashlib.sha256(patched[start:end]).hexdigest(),
            ),
            (
                EL_REGULUS_ATTACK_STATS_PACKED_PATCHED_SIZE,
                EL_REGULUS_ATTACK_STATS_PACKED_PATCHED_SHA256,
            ),
        )
        self.assertEqual(
            len(source_decoded),
            EL_REGULUS_ATTACK_STATS_DECODED_SIZE,
        )
        self.assertEqual(
            len(patched_decoded),
            EL_REGULUS_ATTACK_STATS_DECODED_SIZE,
        )
        self.assertEqual(
            (
                hashlib.sha256(source_decoded).hexdigest(),
                hashlib.sha256(patched_decoded).hexdigest(),
            ),
            (
                EL_REGULUS_ATTACK_STATS_DECODED_SOURCE_SHA256,
                EL_REGULUS_ATTACK_STATS_DECODED_PATCHED_SHA256,
            ),
        )

        expected_changed = {
            index * EL_REGULUS_ATTACK_RECORD_SIZE
            + EL_REGULUS_ATTACK_POWER_OFFSET
            for index in range(3)
        }
        aerods_start = (
            EL_REGULUS_AERODS_RECORD_INDEX * EL_REGULUS_ATTACK_RECORD_SIZE
        )
        expected_changed.update(
            {
                aerods_start + EL_REGULUS_ATTACK_POWER_OFFSET,
                aerods_start + EL_REGULUS_ATTACK_FUEL_OFFSET,
                aerods_start + EL_REGULUS_ATTACK_FUEL_OFFSET + 1,
            }
        )
        actual_changed = {
            index
            for index, (before, after) in enumerate(
                zip(
                    source_decoded,
                    patched_decoded[:EL_REGULUS_ATTACK_STATS_DECODED_SIZE],
                    strict=True,
                )
            )
            if before != after
        }
        self.assertEqual(actual_changed, expected_changed)
        self.assertEqual(
            tuple(patched_decoded[offset] for offset in sorted(expected_changed)),
            (
                *EL_REGULUS_ATTACK_PATCHED_POWERS,
                EL_REGULUS_AERODS_PATCHED_POWER,
                EL_REGULUS_AERODS_PATCHED_FUEL & 0xFF,
                EL_REGULUS_AERODS_PATCHED_FUEL >> 8,
            ),
        )
        self.assertEqual(
            tuple(source_decoded[offset] for offset in sorted(expected_changed)),
            (
                *EL_REGULUS_ATTACK_SOURCE_POWERS,
                EL_REGULUS_AERODS_SOURCE_POWER,
                EL_REGULUS_AERODS_SOURCE_FUEL & 0xFF,
                EL_REGULUS_AERODS_SOURCE_FUEL >> 8,
            ),
        )
        aerods_end = aerods_start + EL_REGULUS_ATTACK_RECORD_SIZE
        self.assertEqual(
            source_decoded[aerods_start:aerods_end],
            EL_REGULUS_AERODS_SOURCE_RECORD,
        )
        self.assertEqual(
            patched_decoded[aerods_start:aerods_end],
            EL_REGULUS_AERODS_PATCHED_RECORD,
        )
        self.assertEqual(
            (
                struct.unpack_from("<H", source_decoded, aerods_start)[0],
                struct.unpack_from(
                    "<h",
                    source_decoded,
                    aerods_start + EL_REGULUS_ATTACK_ANIMATION_OFFSET,
                )[0],
                source_decoded[aerods_start + EL_REGULUS_ATTACK_POWER_OFFSET],
                struct.unpack_from(
                    "<H",
                    source_decoded,
                    aerods_start + EL_REGULUS_ATTACK_FUEL_OFFSET,
                )[0],
                patched_decoded[aerods_start + EL_REGULUS_ATTACK_POWER_OFFSET],
                struct.unpack_from(
                    "<H",
                    patched_decoded,
                    aerods_start + EL_REGULUS_ATTACK_FUEL_OFFSET,
                )[0],
            ),
            (
                0x1001,
                EL_REGULUS_AERODS_ANIMATION_ID,
                EL_REGULUS_AERODS_SOURCE_POWER,
                EL_REGULUS_AERODS_SOURCE_FUEL,
                EL_REGULUS_AERODS_PATCHED_POWER,
                EL_REGULUS_AERODS_PATCHED_FUEL,
            ),
        )
        # Archive entry 26 is Bart's/Brigandier's system row, not Gear 10.
        bart_start, bart_end = offsets[26], offsets[27]
        self.assertNotEqual(26, EL_REGULUS_ATTACK_STATS_ARCHIVE_ENTRY)
        self.assertEqual(
            patched[bart_start:bart_end],
            source[bart_start:bart_end],
        )
        bart_decoded, _ = _decode_lzss_complete_groups(
            source[bart_start:bart_end]
        )
        bart_aerods = (
            EL_REGULUS_AERODS_RECORD_INDEX * EL_REGULUS_ATTACK_RECORD_SIZE
        )
        self.assertEqual(
            (
                struct.unpack_from("<H", bart_decoded, bart_aerods)[0],
                bart_decoded[bart_aerods + EL_REGULUS_ATTACK_POWER_OFFSET],
                struct.unpack_from(
                    "<H",
                    bart_decoded,
                    bart_aerods + EL_REGULUS_ATTACK_FUEL_OFFSET,
                )[0],
            ),
            (0x1002, 60, 600),
        )
        self.assertEqual(
            tuple(
                struct.unpack_from(
                    "<H",
                    patched_decoded,
                    index * EL_REGULUS_ATTACK_RECORD_SIZE
                    + EL_REGULUS_ATTACK_FUEL_OFFSET,
                )[0]
                for index in range(3)
            ),
            EL_REGULUS_ATTACK_FUEL_COSTS,
        )
        for record_index, animation_id, power, fuel_cost in zip(
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_RECORD_INDICES,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_ANIMATION_IDS,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_POWERS,
            EL_REGULUS_LEVEL_ONE_DEATHBLOW_FUEL_COSTS,
            strict=True,
        ):
            record = record_index * EL_REGULUS_ATTACK_RECORD_SIZE
            with self.subTest(level_one_stats_record=record_index):
                self.assertEqual(
                    struct.unpack_from(
                        "<h",
                        source_decoded,
                        record + EL_REGULUS_ATTACK_ANIMATION_OFFSET,
                    )[0],
                    animation_id,
                )
                self.assertEqual(
                    source_decoded[
                        record + EL_REGULUS_ATTACK_POWER_OFFSET
                    ],
                    power,
                )
                self.assertEqual(
                    struct.unpack_from(
                        "<H",
                        source_decoded,
                        record + EL_REGULUS_ATTACK_FUEL_OFFSET,
                    )[0],
                    fuel_cost,
                )
                self.assertEqual(
                    patched_decoded[
                        record :
                        record + EL_REGULUS_ATTACK_RECORD_SIZE
                    ],
                    source_decoded[
                        record :
                        record + EL_REGULUS_ATTACK_RECORD_SIZE
                    ],
                )
        for record_index, animation_id, power, fuel_cost in zip(
            EL_REGULUS_HIGHER_DEATHBLOW_RECORD_INDICES,
            EL_REGULUS_HIGHER_DEATHBLOW_ANIMATION_IDS,
            EL_REGULUS_HIGHER_DEATHBLOW_POWERS,
            EL_REGULUS_HIGHER_DEATHBLOW_FUEL_COSTS,
            strict=True,
        ):
            record = record_index * EL_REGULUS_ATTACK_RECORD_SIZE
            with self.subTest(higher_stats_record=record_index):
                self.assertEqual(
                    struct.unpack_from(
                        "<h",
                        source_decoded,
                        record + EL_REGULUS_ATTACK_ANIMATION_OFFSET,
                    )[0],
                    animation_id,
                )
                self.assertEqual(
                    source_decoded[
                        record + EL_REGULUS_ATTACK_POWER_OFFSET
                    ],
                    power,
                )
                self.assertEqual(
                    struct.unpack_from(
                        "<H",
                        source_decoded,
                        record + EL_REGULUS_ATTACK_FUEL_OFFSET,
                    )[0],
                    fuel_cost,
                )
                self.assertEqual(
                    patched_decoded[
                        record :
                        record + EL_REGULUS_ATTACK_RECORD_SIZE
                    ],
                    source_decoded[
                        record :
                        record + EL_REGULUS_ATTACK_RECORD_SIZE
                    ],
                )

