    def test_current_v167_release_uses_vierge_and_archives_el_regulus(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        metadata = json.loads(
            (
                project
                / "modules" / "mass_driver" / "content"
                / "reconstruction_metadata.json"
            ).read_text(encoding="utf-8")
        )
        release = metadata["current_release"]
        self.assertEqual(metadata["implementation_version"], "v167")
        self.assertEqual(
            metadata["current_document"],
            "docs/mass-driver-dungeon-3.23.md",
        )
        self.assertEqual(
            (
                release["version"],
                release["active_elly_gear"],
                release["active_elly_gear_id"],
                release["el_regulus_archive_installed"],
                release["manifest_jobs"],
                release["declared_replacements"],
                release["declared_replacement_bytes"],
            ),
            ("v167", "Vierge", 2, False, 133, 166, 11_871_218),
        )
        self.assertEqual(
            metadata["party"]["boss"]["playable_pilots"][0]["gear"],
            "Vierge",
        )
        self.assertEqual(
            metadata["party"]["boss"]["playable_pilots"][0]["gear_id"],
            mass_driver.VIERGE_GEAR_ID,
        )

        for key, size_key, sha_key in (
            ("disc_image", "disc_size", "disc_sha256"),
            ("cue", "cue_size", "cue_sha256"),
            ("manifest", "manifest_size", "manifest_sha256"),
        ):
            path = project / release[key]
            self.assertTrue(path.is_file())
            payload = path.read_bytes()
            self.assertEqual(
                (len(payload), hashlib.sha256(payload).hexdigest()),
                (release[size_key], release[sha_key]),
            )

        manifest = json.loads((project / release["manifest"]).read_text())
        replacements = tuple(
            replacement
            for job in manifest["jobs"]
            for replacement in job["replacements"]
        )
        self.assertEqual((len(manifest["jobs"]), len(replacements)), (133, 166))
        self.assertEqual(
            sum(record["size"] for record in replacements),
            11_871_218,
        )
        records = {record["canonical_id"]: record for record in replacements}
        dedicated_el_regulus_ids = set(
            mass_driver.ARCHIVED_EL_REGULUS_CANONICAL_IDS
        ) - {29, 2594, 2614}
        self.assertFalse(dedicated_el_regulus_ids & set(records))
        self.assertEqual(
            {
                canonical_id: (records[canonical_id]["size"], records[canonical_id]["sha256"])
                for canonical_id in (29, 2594, 2595, 2614, 1374)
            },
            {
                29: (13_680, mass_driver.FACILITY_VIDEO_ONLY_SYSTEM_NAMES_PATCHED_SHA256),
                2594: (40_524, mass_driver.FACILITY_VIDEO_ONLY_SYSTEM_DATA_PATCHED_SHA256),
                # This manifest is frozen V167 evidence, including its
                # former level-70 test party; it is not the current state.
                2595: (9_048, "af23f2082f42ea7874edf0b97fd720ce04419a7bb52f75081d570b5f4b4e9cc7"),
                2614: (56_344, NORMAL_ENEMY_BATTLE_STATS_SHA256),
                1374: (162_300, "f7c3c104d021220d6b8c954d1d7d79eacdcdc8d3c936c44cd4ffab8969321904"),
            },
        )
        self.assertEqual(
            release["validation"],
            {
                "native_publisher_title_boot": True,
                "final_bin_payload_extraction": "166/166",
                "replacement_sectors_mode2_form1_edc_ecc_valid": "5877/5877",
                "dedicated_el_regulus_payloads_present": 0,
            },
        )

        # Preserve the accepted V167 launcher contract against its exact
        # archived copy. The generic output launcher now follows the current
        # checked project release and must not remain pinned to V167.
        launcher = (
            project / "archive" / "launchers_before_shared_workflow"
            / "PLAY_MASS_DRIVER_STANDALONE.cmd"
        ).read_text(encoding="utf-8")
        self.assertIn("mass_driver_standalone_v167.cue", launcher)
        self.assertIn("V167 restores Elly's regular Vierge", launcher)
        self.assertIn("El-Regulus is preserved as a future-resource archive", launcher)
        cue = (project / release["cue"]).read_text(encoding="ascii")
        self.assertIn("mass_driver_standalone_v167.bin", cue)

    def test_generic_mass_driver_launcher_delegates_to_current_project_route(self) -> None:
        launcher = (
            REPOSITORY_ROOT / "output" / "PLAY_MASS_DRIVER_STANDALONE.cmd"
        ).read_text(encoding="utf-8")
        self.assertEqual(
            [line.strip() for line in launcher.splitlines() if line.strip()],
            [
                "@echo off",
                'call "%~dp0..\\PLAY_MASS_DRIVER.cmd"',
                "exit /b %ERRORLEVEL%",
            ],
        )

    def test_launcher_and_metadata_preserve_the_frozen_v161_release(self) -> None:
        project = REPOSITORY_ROOT
        metadata_path = (
            project / "modules" / "mass_driver" / "content" / "reconstruction_metadata.json"
        )
        metadata_payload = metadata_path.read_bytes()

        def reject_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
            result: dict[str, object] = {}
            for key, value in pairs:
                if key in result:
                    raise ValueError(f"duplicate metadata key: {key}")
                result[key] = value
            return result

        metadata = json.loads(
            metadata_payload.decode("utf-8"),
            object_pairs_hook=reject_duplicate_keys,
        )
        if metadata["implementation_version"] != "v161":
            self.skipTest("V161 release audit is frozen; V167 is now current")
        release = metadata["release"]
        if not (project / release["manifest"]).is_file():
            self.skipTest("frozen V161 staging artifacts are not present locally")
        current_delta = metadata["v161_release_delta"]
        frozen_v160_delta = metadata["v160_release_delta"]
        delta = metadata["v159_release_delta"]
        frozen_v158_delta = metadata["v158_release_delta"]
        frozen_v157_delta = metadata["v157_release_delta"]
        target_376 = release["target_376_bundle"]
        target_384 = release["target_384_bundle"]
        target_728 = release["target_728_bundle"]
        el_regulus_battle_animation = release["el_regulus_battle_animation"]
        defense_archive_policy = metadata["progression"][
            "control_and_archive_terminal_policy"
        ]["defense_archive"]["north_lift"]
        lower_access_lift = metadata["progression"]["defense_archive"][
            "lower_access_lift"
        ]
        progression = metadata["progression"][
            "control_and_archive_terminal_policy"
        ]["central_control"]
        central_finale = metadata["completion"]["central_control_finale"]
        assistant = metadata["completion"]["final_launch_assistant"]
        continuation = metadata["continuation_state"]

        def canonical_sha256(value: object) -> str:
            payload = json.dumps(
                value, sort_keys=True, separators=(",", ":")
            ).encode("utf-8")
            return hashlib.sha256(payload).hexdigest()

        launcher_path = project / "output" / "PLAY_MASS_DRIVER_STANDALONE.cmd"
        notes_path = project / "docs" / "mass-driver-dungeon-3.22.md"
        frozen_notes_path = project / "docs" / "mass-driver-dungeon-3.21.md"
