    def test_repair_bot_shop_catalogs_use_isolated_expanded_records(self) -> None:
        project = REPOSITORY_ROOT
        source = (project / "work" / "shop_menu_data" / "2593.bin").read_bytes()
        patched = _patch_menu_shop_catalogs(source)
        expected_hash = (
            "b79a34a6db74235a2423cab748155c00eb4b7c69e367cbd59a06fbea683467a6"
        )

        self.assertEqual(MENU_SHOP_CATALOG_PATCHED_SHA256, expected_hash)
        self.assertEqual(len(patched), 65528)
        self.assertEqual(hashlib.sha256(patched).hexdigest(), expected_hash)
        for entry_index, original_size, expected_padding in (
            (ITEM_SHOP_ARCHIVE_ENTRY, ITEM_SHOP_ARCHIVE_DECODED_SIZE, 7),
            (GEAR_SHOP_ARCHIVE_ENTRY, GEAR_SHOP_ARCHIVE_DECODED_SIZE, 5),
        ):
            packed_entry = _menu_archive_entry(patched, entry_index)
            runtime_decoded, consumed = _decode_lzss_complete_groups(packed_entry)
            with self.subTest(runtime_lzss_entry=entry_index):
                self.assertLessEqual(consumed, len(packed_entry))
                self.assertEqual(
                    len(runtime_decoded),
                    original_size + expected_padding,
                )
                self.assertEqual(
                    runtime_decoded[original_size:],
                    bytes(expected_padding),
                )

        retail_items = _decoded_menu_archive_entry(
            source,
            ITEM_SHOP_ARCHIVE_ENTRY,
            ITEM_SHOP_ARCHIVE_DECODED_SIZE,
        )
        patched_items = _decoded_menu_archive_entry(
            patched,
            ITEM_SHOP_ARCHIVE_ENTRY,
            ITEM_SHOP_ARCHIVE_DECODED_SIZE,
        )
        self.assertEqual(
            _shop_group(
                retail_items,
                record=ITEM_SHOP_BASE_ID,
                record_size=ITEM_SHOP_RECORD_SIZE,
                group_offset=ITEM_SHOP_ITEM_OFFSET,
                capacity=ITEM_SHOP_ITEM_CAPACITY,
            ),
            ITEM_SHOP_ORIGINAL_IDS,
        )
        self.assertEqual(
            _shop_group(
                patched_items,
                record=ITEM_SHOP_BASE_ID,
                record_size=ITEM_SHOP_RECORD_SIZE,
                group_offset=ITEM_SHOP_ITEM_OFFSET,
                capacity=ITEM_SHOP_ITEM_CAPACITY,
            ),
            ITEM_SHOP_ORIGINAL_IDS,
        )
        self.assertEqual(
            _shop_group(
                retail_items,
                record=ITEM_SHOP_MERGE_SOURCE_ID,
                record_size=ITEM_SHOP_RECORD_SIZE,
                group_offset=ITEM_SHOP_ITEM_OFFSET,
                capacity=ITEM_SHOP_ITEM_CAPACITY,
            ),
            ITEM_SHOP_MERGE_SOURCE_IDS,
        )
        self.assertEqual(
            _shop_group(
                patched_items,
                record=ITEM_SHOP_MERGE_SOURCE_ID,
                record_size=ITEM_SHOP_RECORD_SIZE,
                group_offset=ITEM_SHOP_ITEM_OFFSET,
                capacity=ITEM_SHOP_ITEM_CAPACITY,
            ),
            ITEM_SHOP_MERGE_SOURCE_IDS,
        )
        self.assertEqual(
            _shop_group(
                retail_items,
                record=ITEM_SHOP_ID,
                record_size=ITEM_SHOP_RECORD_SIZE,
                group_offset=ITEM_SHOP_ITEM_OFFSET,
                capacity=ITEM_SHOP_ITEM_CAPACITY,
            ),
            (),
        )
        self.assertEqual(
            _shop_group(
                patched_items,
                record=ITEM_SHOP_ID,
                record_size=ITEM_SHOP_RECORD_SIZE,
                group_offset=ITEM_SHOP_ITEM_OFFSET,
                capacity=ITEM_SHOP_ITEM_CAPACITY,
            ),
            ITEM_SHOP_EXPANDED_IDS,
        )

        items_with_target_restored = bytearray(patched_items)
        item_target_start = (
            ITEM_SHOP_ID * ITEM_SHOP_RECORD_SIZE + ITEM_SHOP_ITEM_OFFSET
        )
        item_target_end = item_target_start + ITEM_SHOP_ITEM_CAPACITY
        items_with_target_restored[item_target_start:item_target_end] = (
            retail_items[item_target_start:item_target_end]
        )
        self.assertEqual(bytes(items_with_target_restored), retail_items)

        retail_gear = _decoded_menu_archive_entry(
            source,
            GEAR_SHOP_ARCHIVE_ENTRY,
            GEAR_SHOP_ARCHIVE_DECODED_SIZE,
        )
        patched_gear = _decoded_menu_archive_entry(
            patched,
            GEAR_SHOP_ARCHIVE_ENTRY,
            GEAR_SHOP_ARCHIVE_DECODED_SIZE,
        )
        for group in range(GEAR_SHOP_GROUP_COUNT):
            group_offset = group * GEAR_SHOP_GROUP_CAPACITY
            with self.subTest(gear_group=group):
                self.assertEqual(
                    _shop_group(
                        retail_gear,
                        record=GEAR_SHOP_BASE_ID,
                        record_size=GEAR_SHOP_RECORD_SIZE,
                        group_offset=group_offset,
                        capacity=GEAR_SHOP_GROUP_CAPACITY,
                    ),
                    GEAR_SHOP_ORIGINAL_GROUPS[group],
                )
                self.assertEqual(
                    _shop_group(
                        patched_gear,
                        record=GEAR_SHOP_BASE_ID,
                        record_size=GEAR_SHOP_RECORD_SIZE,
                        group_offset=group_offset,
                        capacity=GEAR_SHOP_GROUP_CAPACITY,
                    ),
                    GEAR_SHOP_ORIGINAL_GROUPS[group],
                )
                self.assertEqual(
                    _shop_group(
                        retail_gear,
                        record=GEAR_SHOP_MERGE_SOURCE_ID,
                        record_size=GEAR_SHOP_RECORD_SIZE,
                        group_offset=group_offset,
                        capacity=GEAR_SHOP_GROUP_CAPACITY,
                    ),
                    GEAR_SHOP_MERGE_SOURCE_GROUPS[group],
                )
                self.assertEqual(
                    _shop_group(
                        patched_gear,
                        record=GEAR_SHOP_MERGE_SOURCE_ID,
                        record_size=GEAR_SHOP_RECORD_SIZE,
                        group_offset=group_offset,
                        capacity=GEAR_SHOP_GROUP_CAPACITY,
                    ),
                    GEAR_SHOP_MERGE_SOURCE_GROUPS[group],
                )
                self.assertEqual(
                    _shop_group(
                        retail_gear,
                        record=GEAR_SHOP_ID,
                        record_size=GEAR_SHOP_RECORD_SIZE,
                        group_offset=group_offset,
                        capacity=GEAR_SHOP_GROUP_CAPACITY,
                    ),
                    (),
                )
                self.assertEqual(
                    _shop_group(
                        patched_gear,
                        record=GEAR_SHOP_ID,
                        record_size=GEAR_SHOP_RECORD_SIZE,
                        group_offset=group_offset,
                        capacity=GEAR_SHOP_GROUP_CAPACITY,
                    ),
                    GEAR_SHOP_EXPANDED_GROUPS[group],
                )

        gear_with_target_restored = bytearray(patched_gear)
        gear_target_start = GEAR_SHOP_ID * GEAR_SHOP_RECORD_SIZE
        gear_target_end = gear_target_start + GEAR_SHOP_RECORD_SIZE
        gear_with_target_restored[gear_target_start:gear_target_end] = retail_gear[
            gear_target_start:gear_target_end
        ]
        self.assertEqual(bytes(gear_with_target_restored), retail_gear)

    def test_title_menu_labels_use_field_local_texture_and_disabled_rows(self) -> None:
        project = REPOSITORY_ROOT
        source = (project / "work" / "shop_menu_data" / "2593.bin").read_bytes()
        patched = _patch_menu_shop_catalogs(source)
        _, source_entries = mass_driver._menu_archive_entries(source)

        source_images = mass_driver._decode_menu_archive_entry(
            source_entries[mass_driver.TITLE_MENU_IMAGE_ARCHIVE_ENTRY],
            expected_size=mass_driver.TITLE_MENU_IMAGE_DECODED_SIZE,
            expected_sha256=mass_driver.TITLE_MENU_IMAGE_DECODED_SHA256,
            label="source title images",
        )
        self.assertEqual(
            _menu_archive_entry(
                patched, mass_driver.TITLE_MENU_IMAGE_ARCHIVE_ENTRY
            ),
            source_entries[mass_driver.TITLE_MENU_IMAGE_ARCHIVE_ENTRY],
        )

        source_font = mass_driver._decode_menu_archive_entry(
            source_entries[mass_driver.TITLE_MENU_FONT_ARCHIVE_ENTRY],
            expected_size=mass_driver.TITLE_MENU_FONT_DECODED_SIZE,
            expected_sha256=mass_driver.TITLE_MENU_FONT_DECODED_SHA256,
            label="source title font",
        )
        patched_font, consumed = mass_driver._decode_lzss_complete_groups(
            _menu_archive_entry(patched, mass_driver.TITLE_MENU_FONT_ARCHIVE_ENTRY)
        )
        self.assertLessEqual(
            consumed,
            len(_menu_archive_entry(patched, mass_driver.TITLE_MENU_FONT_ARCHIVE_ENTRY)),
        )
        self.assertEqual(len(patched_font), mass_driver.TITLE_MENU_PATCHED_FONT_SIZE)
        self.assertEqual(
            hashlib.sha256(patched_font).hexdigest(),
            mass_driver.TITLE_MENU_PATCHED_FONT_SHA256,
        )
        _, _, source_records = mass_driver._title_menu_font_records(source_font)
        _, _, patched_records = mass_driver._title_menu_font_records(patched_font)
        expected = (
            (0x123, 0, 180, 68, 9, -74, 10, 304, 509),
            (0x124, 72, 180, 136, 9, -74, 29, 272, 509),
            (0x125, 209, 180, 46, 9, -74, 49, 272, 509),
        )
        for glyph, u, v, width, height, dx, dy, clut_x, clut_y in expected:
            record = patched_records[glyph]
            self.assertEqual(struct.unpack_from("<HH", record, 0), (1, 0))
            values = struct.unpack_from("<14h", record, 4)
            with self.subTest(title_glyph=hex(glyph)):
                self.assertEqual(values[:6], (u, v, width, height, dx, dy))
                self.assertEqual(values[6:9], (4, 0, 0))
                self.assertEqual(values[9:13], (clut_x, clut_y, 960, 180))
                self.assertLessEqual(u + width, 255)
        for index, (before, after) in enumerate(
            zip(source_records, patched_records, strict=True)
        ):
            if index not in mass_driver.TITLE_MENU_LABEL_GLYPHS:
                self.assertEqual(after, before)

        atlas, rebuilt_font = mass_driver._build_title_menu_labels(
            source_images, source_font
        )
        self.assertEqual(rebuilt_font, patched_font)
        self.assertEqual(len(atlas), 256 * 9 // 2)
        self.assertEqual(
            hashlib.sha256(atlas).hexdigest(),
            mass_driver.TITLE_MENU_LABEL_TEXTURE_SHA256,
        )
        pixels = []
        for packed in atlas:
            pixels.extend((packed & 0x0F, packed >> 4))
        for index, (u, width) in enumerate(
            zip(
                mass_driver.TITLE_MENU_LABEL_TEXTURE_U,
                mass_driver.TITLE_MENU_LABEL_WIDTHS,
                strict=True,
            )
        ):
            values = {
                pixels[y * mass_driver.TITLE_MENU_LABEL_TEXTURE_WIDTH + x]
                for y in range(mass_driver.TITLE_MENU_LABEL_TEXTURE_HEIGHT)
                for x in range(u, u + width)
            }
            self.assertIn(0, values)
            self.assertGreater(len(values), 2)
            self.assertEqual(max(values), 15 if index == 0 else 11)
            self.assertGreaterEqual(min(values - {0}), 9 if index == 0 else 5)

    def test_title_menu_graphics_removes_branding_and_reuses_only_padding(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        source = (
            project / "work" / "title_menu_audit_20260813" / "1587.bin"
        ).read_bytes()
        retail = (
            project
            / "work"
            / "title_menu_audit_20260813"
            / "retail"
            / "1587.bin"
        ).read_bytes()
        atlas = mass_driver._title_menu_label_atlas(project / "work")
        branding_free = mass_driver._remove_title_menu_branding(source, retail)
        patched = mass_driver._patch_title_menu_graphics(source, atlas, retail)
        height_offset = mass_driver.TITLE_MENU_GRAPHICS_LAST_CHUNK_HEIGHT_OFFSET
        atlas_offset = mass_driver.TITLE_MENU_GRAPHICS_LABEL_PIXELS_OFFSET
        atlas_end = atlas_offset + len(atlas)

        self.assertEqual(
            hashlib.sha256(branding_free).hexdigest(),
            mass_driver.TITLE_MENU_GRAPHICS_BRANDING_FREE_SHA256,
        )
        changed_words = 0
        x, y, width, height = mass_driver.TITLE_MENU_BRANDING_RECT
        branding_offsets = set()
        for row in range(y, y + height):
            for column in range(x, x + width):
                offset = mass_driver._title_menu_framebuffer_pixel_offset(
                    column, row
                )
                branding_offsets.update((offset, offset + 1))
                source_word = struct.unpack_from("<H", source, offset)[0]
                retail_word = struct.unpack_from("<H", retail, offset)[0]
                restored_word = struct.unpack_from("<H", branding_free, offset)[0]
                self.assertEqual(restored_word, (retail_word & 0x7FFF) | 0x8000)
                changed_words += source_word != restored_word
        self.assertEqual(changed_words, 389)
        changed_bytes = {
            index
            for index, (before, after) in enumerate(
                zip(source, branding_free, strict=True)
            )
            if before != after
        }
        self.assertEqual(len(changed_bytes), 716)
        self.assertTrue(changed_bytes <= branding_offsets)

        self.assertEqual(len(patched), len(source))
        self.assertEqual(
            hashlib.sha256(patched).hexdigest(),
            mass_driver.TITLE_MENU_GRAPHICS_PATCHED_SHA256,
        )
        self.assertEqual(struct.unpack_from("<H", source, height_offset)[0], 4)
        self.assertEqual(struct.unpack_from("<H", patched, height_offset)[0], 13)
        self.assertEqual(patched[atlas_offset:atlas_end], atlas)
        self.assertEqual(patched[:height_offset], branding_free[:height_offset])
        self.assertEqual(
            patched[height_offset + 2 : atlas_offset],
            branding_free[height_offset + 2 : atlas_offset],
        )
        self.assertEqual(patched[atlas_end:], branding_free[atlas_end:])
        self.assertEqual(atlas_offset, 0x2C200)
        self.assertEqual(atlas_end, 0x2C680)

