    def _assert_hardened_external_door(
        self,
        script: AtelScript,
        *,
        entity: int,
        action_pointer: int,
        collision_pointer: int,
        helpers: tuple[int, ...],
        party_script: int,
        movement_x: int,
        movement_z: int,
        destination: int,
        parameter: int,
        tail: bytes = b"\x00",
    ) -> None:
        """Assert the exact finite action used by a reciprocal route door."""

        self.assertEqual(script.get_script_pointer(entity, 2), action_pointer)
        self.assertEqual(script.get_script_pointer(entity, 3), collision_pointer)
        expected_action = (
            b"\x07\xFF"
            + bytes((party_script | 0x20,))
            + bytes.fromhex("FE 54 74 77 80")
            + b"".join(b"\x07" + bytes((helper, 0x24)) for helper in helpers)
            + _wait(84)
            + b"\x0E"
            + _change_field(destination, parameter)
            + tail
        )
        self.assertEqual(
            script.bytecode[
                action_pointer : action_pointer + len(expected_action)
            ],
            expected_action,
        )
        for helper in helpers:
            self.assertNotIn(
                b"\x09" + bytes((helper, 0x24)),
                expected_action,
            )
        self.assertLess(
            expected_action.index(b"\x07\xFF"),
            expected_action.index(b"\xFE\x54"),
        )

        expected_movement = _wait(32) + _party_actor_waypoint_script(
            movement_x,
            movement_z,
            48,
        )
        movement_pointer = script.get_script_pointer(2, party_script)
        self.assertGreater(movement_pointer, 0)
        self.assertEqual(
            script.bytecode[
                movement_pointer : movement_pointer + len(expected_movement)
            ],
            expected_movement,
        )
        for party_entity in range(2, 13):
            with self.subTest(
                bounded_party_entity=party_entity,
                bounded_party_script=party_script,
            ):
                self.assertEqual(
                    script.get_script_pointer(party_entity, party_script),
                    movement_pointer,
                )

