            self.assertIn(b"\x07" + bytes((helper_entity, 0x24)), action)
            self.assertIn(_change_field(destination, parameter), action)
            helper = _pointed_script_body(
                transformed,
                transformed.get_script_pointer(helper_entity, 4),
            )
            self.assertEqual((helper[0], helper[-1]), (0x37, 0x00))

