    def test_auxiliary_terminal_role_verifier_rejects_mail_on_floor_switch(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        required_fields = (
            361,
            366,
            367,
            368,
            369,
            370,
            371,
            376,
            377,
            378,
            379,
            382,
            383,
            724,
            728,
        )
        prepared = [
            _prepare_clone(
                _clone(field),
                project / "work",
                project / "modules" / "mass_driver" / "content",
            )
            for field in required_fields
        ]
        self.assertIsNone(verify_control_and_archive_terminal_roles(prepared))

        index = next(
            index
            for index, item in enumerate(prepared)
            if item.target_field == 361
        )
        item = prepared[index]
        components = list(item.components)
        editor = AtelScript(components[SCRIPT_INDEX])
        editor.set_script_pointer(
            16,
            2,
            editor.get_script_pointer(12, 2),
        )
        components[SCRIPT_INDEX] = editor.to_bytes()
        prepared[index] = replace(item, components=tuple(components))

        with self.assertRaisesRegex(
            DungeonBuildError,
            "Auxiliary room lost its dual-floor-switch/hanging-mail separation",
        ):
            verify_control_and_archive_terminal_roles(prepared)

