    def test_field_384_approaches_adjacent_gears_then_battles_and_dismounts(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        archive = _clone(376)
        lift = archive.defense_bay_lift_exit
        assert lift is not None
        self.assertEqual(
            (
                lift.controller_entity,
                lift.helper_entities,
                lift.controller_x,
                lift.controller_z,
                lift.model_x,
                lift.model_z,
                lift.model_indices,
                lift.frame_model_index,
                lift.y_rotation,
                lift.required_mask,
                lift.interaction_half_width,
                lift.interaction_half_width * 2 + 16,
                lift.new_field,
                lift.new_parameter,
            ),
            (
                17,
                (18, 19),
                0,
                308,
                0,
                0,
                (17, 18),
                19,
                0,
                LAUNCH_AUTHORIZATION_MASK,
                0x0B,
                38,
                384,
                0,
            ),
        )
        self.assertEqual(
            archive.field_entry_additions,
            (
                FieldEntryAddition(-470, 0, 0),
                FieldEntryAddition(0, 245, 0),
            ),
        )
        _archive_donor, archive_script = _donor_and_transformed(376)
        self.assertEqual(archive_script.entity_count, 28)
        lift_pointers = tuple(
            archive_script.get_script_pointer(lift.controller_entity, index)
            for index in range(4)
        )
        self.assertEqual(lift_pointers, (0x0775, 0x5FDB, 0x079C, 0x05C2))
        lift_init = _pointed_script_body(archive_script, lift_pointers[0])
        self.assertEqual(
            lift_init,
            _static_door_controller_init(
                0,
                308,
                requires_facing=False,
                interaction_half_width=0x0B,
            ),
        )
        self.assertEqual(
            (lift_init[7:11], lift_init[11:15], lift_init[16:18]),
            (
                bytes.fromhex("F8 00 00 20"),
                bytes.fromhex("F8 07 04 00"),
                bytes.fromhex("0B 0B"),
            ),
        )
        lift_worker = _pointed_script_body(archive_script, lift_pointers[1])
        self.assertEqual(
            (
                len(lift_worker),
                hashlib.sha256(lift_worker).hexdigest(),
            ),
            (
                62,
                "5d3f33f4171393f400c460552dd3e638cb1bc6cb8214d221de959f700be4ee1f",
            ),
        )
        lift_action = _pointed_script_body(
            archive_script,
            lift_pointers[2],
        )
        lift_collision = _pointed_script_body(
            archive_script,
            lift_pointers[3],
        )
        authorization_guard = (
            bytes.fromhex("02 FE 03")
            + struct.pack("<H", LAUNCH_AUTHORIZATION_MASK)
            + b"\x46"
        )
        self.assertEqual(LAUNCH_AUTHORIZATION_MASK, 1 << 4)
        self.assertTrue(lift_action.startswith(authorization_guard))
        self.assertEqual(lift_collision, b"\x00")
        authorized_transition = (
            mass_driver._defense_bay_lift_transition_body(lift, 30)
        )
        self.assertEqual(lift_action.count(authorized_transition), 1)
        self.assertIn(_change_field(384, 0), lift_action)
        self.assertNotIn(b"\xFE\x68", lift_action)
        locked_feedback = _automatic_dialogue_body(
            (lift.locked_dialogue,),
            routine_pc=lift_pointers[2] + len(lift_action) - 25,
        )
        self.assertIn(_dialog(lift.locked_dialogue), lift_action)
        self.assertNotIn(_dialog(lift.locked_dialogue), lift_collision)
        self.assertTrue(lift_action.endswith(locked_feedback + b"\x00"))
        lift_poll_pointer = archive_script.get_script_pointer(0, 1)
        lift_poll = _pointed_script_body(archive_script, lift_poll_pointer)
        expected_lift_poll = bytes.fromhex(
            "02 FE 03 10 00 46 13 08 "
            "2D FF F8 07 FA 07 FC 07 "
            "02 F8 07 D4 FF 44 13 08 "
            "02 F8 07 2D 00 43 13 08 "
            "02 FA 07 0E 01 44 13 08 "
            "09 11 22 26 00 80 01 E8 07"
        )
        self.assertEqual(
            lift_poll,
            mass_driver._defense_bay_lift_proximity_poll(
                lift_poll_pointer,
                lift,
            ),
        )
        self.assertEqual(lift_poll_pointer, 0x07E8)
        self.assertEqual(lift_poll, expected_lift_poll)
        self.assertEqual(
            (len(lift_poll), hashlib.sha256(lift_poll).hexdigest()),
            (
                49,
                "edccb868d5ff18565e6473ececd2f4ad3497b66dff783d1e926e97370b7f2536",
            ),
        )
        self.assertTrue(lift_poll.startswith(authorization_guard))
        self.assertNotIn(authorized_transition, lift_poll)
        self.assertNotIn(_change_field(384, 0), lift_poll)
        self.assertEqual(
            lift_poll.count(
                b"\x09" + bytes((lift.controller_entity, 2 | 0x20))
            ),
            1,
        )
        self.assertIn(bytes.fromhex("2D FF F8 07 FA 07 FC 07"), lift_poll)
        self.assertEqual(
            lift_poll[16:32],
            bytes.fromhex(
                # X < -44 and X >= 45 both branch to the shared 0x0813 retry.
                "02 F8 07 D4 FF 44 13 08 "
                "02 F8 07 2D 00 43 13 08"
            ),
        )
        self.assertTrue(
            lift_poll.endswith(
                mass_driver._yield_tick() + _jump(lift_poll_pointer)
            )
        )

        def automatic_lift_selected(
            authorized: bool,
            x: float,
            z: float,
        ) -> bool:
            return (
                authorized
                and mass_driver.DEFENSE_BAY_LIFT_NAVIGABLE_MIN_X
                <= x
                <= mass_driver.DEFENSE_BAY_LIFT_NAVIGABLE_MAX_X
                and z >= mass_driver.DEFENSE_BAY_LIFT_FIRST_CONTACT_Z
            )

        live_x, live_z, _live_triangle = (
            mass_driver.DEFENSE_BAY_LIFT_V158_BLOCKED_CAPTURE
        )
        boundary_cases = (
            (False, 0, 279, False),
            (True, 0, mass_driver.DEFENSE_BAY_LIFT_RETURN_SPAWN_Z, False),
            (True, 0, 269, False),
            (True, 0, 270, True),
            (True, 3.045166, 271.910645, True),
            (True, -44, 274, True),
            (True, 44, 279, True),
            (True, -45, 279, False),
            (True, 45, 279, False),
            (True, live_x, live_z, True),
            # Hold the live return-stair X at the lift's trigger latitude: the
            # explicit horizontal guard must still reject the boss lift.
            (
                True,
                694.87,
                mass_driver.DEFENSE_BAY_LIFT_FIRST_CONTACT_Z,
                False,
            ),
        )
        for authorized, x, z, expected in boundary_cases:
            with self.subTest(authorized=authorized, x=x, z=z):
                self.assertEqual(
                    automatic_lift_selected(authorized, x, z),
                    expected,
                )
        east_return_capture = (694.87, 31.00, 97.21, 110)
        self.assertGreater(
            east_return_capture[0],
            mass_driver.DEFENSE_BAY_LIFT_NAVIGABLE_MAX_X,
        )
        self.assertFalse(
            automatic_lift_selected(
                True,
                east_return_capture[0],
                east_return_capture[2],
            )
        )
        east_return_pointer = archive_script.get_script_pointer(12, 1)
        east_return_body = _pointed_script_body(
            archive_script,
            east_return_pointer,
        )
        self.assertEqual(east_return_pointer, 0x0093)
        self.assertEqual(
            east_return_body,
            bytes.fromhex("CB 00 9C 00 98 D6 82 01 80 00"),
        )
        self.assertEqual(east_return_body.count(_change_field(726, 1)), 1)
        lift_transition_index = lift_action.index(_change_field(384, 0))
        legacy_save_assignments = (
            bytes.fromhex("FE A1 01 80 02 80"),
            bytes.fromhex("FE A1 06 80 09 80"),
        )
        for assignment in legacy_save_assignments:
            self.assertEqual(lift_action.count(assignment), 1)
            self.assertLess(lift_action.index(assignment), lift_transition_index)
        self.assertNotIn(bytes.fromhex("FE A1 01 80 0A 80"), lift_action)
        for slot, staged_bit in (
            (0, EL_REGULUS_STAGED_BIT),
            (1, CRESCENS_STAGED_BIT),
        ):
            unmount = b"\xFE\x42" + struct.pack("<H", slot | 0x8000)
            clear = _clear_var_bit(INTERLOCK_VARIABLE, staged_bit)
            self.assertIn(unmount, lift_action)
            self.assertIn(clear, lift_action)
            self.assertLess(lift_action.index(unmount), lift_transition_index)
            self.assertLess(lift_action.index(clear), lift_transition_index)
        for helper in lift.helper_entities:
            # Authorization opens and leaves the recessed lift at its visible
            # endpoint. Crossing the already-open threshold must not replay
            # the helpers and visibly snap the leaves shut first.
            self.assertNotIn(b"\x07" + bytes((helper, 0x24)), lift_action)
            authorization = archive.authorization_terminal
            assert authorization is not None
            authorization_action = _pointed_script_body(
                archive_script,
                archive_script.get_script_pointer(authorization.entity, 2),
            )
            self.assertIn(
                b"\x07" + bytes((helper, 0x24)),
                authorization_action,
            )
            helper_body = _pointed_script_body(
                archive_script,
                archive_script.get_script_pointer(helper, 4),
            )
            self.assertEqual(len(helper_body), 217)
            self.assertEqual(helper_body[0], 0x19)
            self.assertEqual(helper_body[-1], 0x00)
        prepared_archive = _prepare_clone(
            archive,
            project / "work",
            project / "modules" / "mass_driver" / "content",
        )
        assert prepared_archive.header is not None
        self.assertEqual(
            (
                len(prepared_archive.header),
                struct.unpack_from("<H", prepared_archive.header, 0x18C)[0],
                hashlib.sha256(prepared_archive.header).hexdigest(),
            ),
            (
                DEFENSE_ARCHIVE_RECORD_HEADER_SIZE,
                44,
                DEFENSE_ARCHIVE_RECORD_HEADER_SHA256,
            ),
        )
        controller_offset = 0x190 + lift.controller_entity * 16
        self.assertEqual(
            prepared_archive.header[
                controller_offset : controller_offset + 16
            ],
            _field_actor_record(0x01E0, 0, 308, 0),
        )

        hall = _clone(384)
        self.assertEqual(
            (
                hall.source_field,
                hall.target_bundle_id,
                hall.target_graphics_id,
            ),
            (260, 1374, 1375),
        )
        scene = hall.goliath_factory_hall
        assert scene is not None
        self.assertEqual(
            (
                scene.director_entity,
                scene.old_director_init_pointer,
                scene.old_director_update_pointer,
                scene.gear_entities,
                scene.old_gear_action_pointers,
                scene.gear_dialogues,
                scene.gear_positions,
                scene.staged_bits,
                scene.approach_z,
                scene.south_entity,
                scene.south_helpers,
                scene.north_entity,
                scene.north_helpers,
                scene.north_offline_dialogue,
                scene.south_exit_dialogue,
            ),
            (
                0,
                0x001D,
                0x00AE,
                (1, 2),
                (0x43AB, 0x43C6),
                (1, 2),
                ((-200, -2035), (200, -2035)),
                (EL_REGULUS_STAGED_BIT, CRESCENS_STAGED_BIT),
                -2100,
                10,
                (11, 12),
                13,
                (14, 15),
                5,
                6,
            ),
        )
        _hall_donor, transformed_hall = _donor_and_transformed(384)
        director_init = _pointed_script_body(
            transformed_hall,
            transformed_hall.get_script_pointer(scene.director_entity, 0),
        )
        self.assertIn(_jump(scene.old_director_init_pointer), director_init)
        for variable, value in (
            (0x002C, -200),
            (0x002E, -2035),
            (0x0032, 200),
            (0x0034, -2035),
        ):
            self.assertIn(_set_variable_s16(variable, value), director_init)
        self.assertEqual(
            transformed_hall.bytecode[0x0078:0x007B],
            bytes.fromhex("FE 1E 03"),
        )
        self.assertEqual(
            _read_field_entry(transformed_hall.to_bytes(), 0),
            FieldEntryAddition(0, -2600, 0, 0, 0),
        )
        self.assertEqual(
            tuple(
                (contract.source_field, contract.destination_parameter)
                for contract in ARRIVAL_CONTINUITY_CONTRACTS
                if contract.destination_field == 384
            ),
            ((376, 0),),
        )

        mount_by_slot = (
            bytes.fromhex("FE 41 00 80"),
            bytes.fromhex("FE 41 01 80"),
        )
        staged_write_by_gear = (
            _set_var_bit(INTERLOCK_VARIABLE, EL_REGULUS_STAGED_BIT),
            _set_var_bit(INTERLOCK_VARIABLE, CRESCENS_STAGED_BIT),
        )
        assignment_by_gear = (
            bytes.fromhex("FE A1 01 80 02 80"),
            bytes.fromhex("FE A1 06 80 09 80"),
        )
        for entity in scene.gear_entities:
            action = _pointed_script_body(
                transformed_hall,
                transformed_hall.get_script_pointer(entity, 2),
            )
            self.assertEqual(action, b"\x00")

        routine = _pointed_script_body(
            transformed_hall,
            transformed_hall.get_script_pointer(scene.director_entity, 1),
        )
        # The isolated post-launch recovery prefix also mounts the two Gears.
        # The normal approach/battle path begins at the shared guard target.
        routine_pc = transformed_hall.get_script_pointer(scene.director_entity, 1)
        normal_pc = struct.unpack_from("<H", routine, 6)[0]
        routine = routine[normal_pc - routine_pc :]
        boss = scene.battle
        self.assertEqual(boss.elly_gear, mass_driver.VIERGE_GEAR_ID)
        self.assertEqual(routine.count(bytes.fromhex("FE A1 01 80 0A 80")), 0)
        self.assertEqual(boss.victory_dialogue, 4)
        hall_dialogue = json.loads(
            (
                project
                / "modules" / "mass_driver" / "content"
                / hall.dialogue_file
            ).read_text(encoding="utf-8")
        )
        gear_intro_text = next(
            block["text"] for block in hall_dialogue["blocks"] if block["id"] == 1
        )
        self.assertIn("VIERGE\nPILOT LINK: ELLY", gear_intro_text)
        self.assertNotIn("El-Regulus", gear_intro_text)
        victory_text = next(
            block["text"]
            for block in hall_dialogue["blocks"]
            if block["id"] == boss.victory_dialogue
        )
        normalized_victory = " ".join(victory_text.replace("<New>", " ").split())
        for instruction in (
            "Custodian core offline", "West bulkhead release enabled",
            "control panel is upstairs", "won't fit through the passage upstairs",
            "come back for them after the launch",
        ):
            self.assertIn(instruction, normalized_victory)
        battle = _fixed_battle(boss.configuration)
        battle_index = routine.index(battle)
        self.assertEqual(routine.count(battle), 1)
        battle_music = mass_driver._play_music(
            mass_driver.NORMAL_BATTLE_MUSIC_ID
        )
        self.assertEqual(mass_driver.NORMAL_BATTLE_MUSIC_ID, 0x14)
        self.assertEqual(routine.count(battle_music), 1)
        self.assertEqual(
            routine[
                battle_index - len(battle_music) : battle_index
            ],
            bytes.fromhex("75 14 80"),
        )
        self.assertEqual(
            routine[
                battle_index + len(battle) :
                battle_index + len(battle) + 2
            ],
            bytes.fromhex("FE 7F"),
        )
        victory_write = _set_var_bit(boss.variable, boss.defeated_bit)
        boss_check = bytes.fromhex("02 FE 03 20 00 46")
        authorization_check = (
            bytes.fromhex("02 FE 03")
            + struct.pack("<H", LAUNCH_AUTHORIZATION_MASK)
            + b"\x46"
        )
        el_regulus_check = bytes.fromhex("02 FE 03 00 08 46")
        crescens_check = bytes.fromhex("02 FE 03 00 80 46")
        self.assertIn(boss_check, routine[:battle_index])
        self.assertIn(authorization_check, routine[:battle_index])
        self.assertNotIn(el_regulus_check, routine[:battle_index])
        self.assertNotIn(crescens_check, routine[:battle_index])
        leader_position_poll = bytes.fromhex("2D FF F8 07 FA 07 FC 07")
        approach_check = (
            bytes.fromhex("02 FA 07")
            + struct.pack("<h", scene.approach_z)
            + b"\x44"
        )
        self.assertIn(leader_position_poll, routine[:battle_index])
        self.assertIn(approach_check, routine[:battle_index])
        previous_beat = routine.index(_dialogue_sequence((boss.pre_battle_dialogue,)))
        for dialogue, assignment, mount, staged_write in zip(
            scene.gear_dialogues,
            assignment_by_gear,
            mount_by_slot,
            staged_write_by_gear,
            strict=True,
        ):
            self.assertEqual(routine.count(assignment), 1)
            self.assertEqual(routine.count(mount), 1)
            self.assertEqual(routine.count(staged_write), 1)
            boarding = routine.index(_dialogue_sequence((dialogue,)))
            self.assertLess(previous_beat, boarding)
            self.assertLess(boarding, routine.index(mount))
            self.assertLess(routine.index(mount), routine.index(staged_write))
            previous_beat = routine.index(staged_write)
            self.assertLess(routine.index(assignment), battle_index)
            self.assertLess(routine.index(mount), battle_index)
            self.assertLess(routine.index(staged_write), battle_index)
        self.assertGreater(
            routine.index(_dialogue_sequence((boss.victory_dialogue,))),
            battle_index,
        )
        self.assertNotIn(
            bytes.fromhex("FE A1 02 80 0B 80"),
            routine,
        )
        self.assertEqual(
            routine.count(bytes.fromhex("FE 3B 02 80")),
            1,
        )
        self.assertLess(
            routine.index(bytes.fromhex("FE 3B 02 80")),
            battle_index,
        )
        self.assertNotIn(bytes.fromhex("FE 3A 02 80"), routine)
        self.assertNotIn(bytes.fromhex("FE 42 00 80"), routine)
        self.assertNotIn(bytes.fromhex("FE 42 01 80"), routine)
        self.assertNotIn(
            _clear_var_bit(INTERLOCK_VARIABLE, EL_REGULUS_STAGED_BIT),
            routine,
        )
        self.assertNotIn(
            _clear_var_bit(INTERLOCK_VARIABLE, CRESCENS_STAGED_BIT),
            routine,
        )
        self.assertNotIn(b"\xFE\x18", routine)
        self.assertNotIn(b"\xFE\x1A", routine)
        self.assertGreater(routine.index(victory_write), battle_index)
        visual_reload = _change_field(384, 0)
        self.assertEqual(routine.count(visual_reload), 1)
        self.assertGreater(routine.index(visual_reload), battle_index)
        self.assertGreater(
            routine.index(visual_reload),
            routine.index(_dialogue_sequence((boss.victory_dialogue,))),
        )

        south = _pointed_script_body(
            transformed_hall,
            transformed_hall.get_script_pointer(scene.south_entity, 2),
        )
        south_transition = _change_field(scene.south_field, scene.south_parameter)
        self.assertNotIn(
            _dialogue_sequence((scene.south_exit_dialogue,)),
            south,
        )
        for slot, staged_bit in (
            (0, EL_REGULUS_STAGED_BIT),
            (1, CRESCENS_STAGED_BIT),
        ):
            unmount = b"\xFE\x42" + struct.pack("<H", slot | 0x8000)
            clear = _clear_var_bit(INTERLOCK_VARIABLE, staged_bit)
            self.assertIn(unmount, south)
            self.assertIn(clear, south)
            self.assertLess(south.index(unmount), south.index(south_transition))
            self.assertLess(south.index(clear), south.index(south_transition))
        self.assertIn(south_transition, south)
        for helper in scene.south_helpers:
            self.assertIn(b"\x07" + bytes((helper, 0x24)), south)

        north = _pointed_script_body(
            transformed_hall,
            transformed_hall.get_script_pointer(scene.north_entity, 2),
        )
        self.assertIn(
            _dialogue_sequence((scene.north_offline_dialogue,)),
            north,
        )
        self.assertNotIn(b"\x98", north)
        expected_north_helper_bodies = {
            14: bytes.fromhex("4E BA FF 00 00 C0 00"),
            15: bytes.fromhex("4E 90 00 00 00 C0 00"),
        }
        for helper in scene.north_helpers:
            self.assertNotIn(b"\x09" + bytes((helper, 0x24)), north)
            helper_body = _pointed_script_body(
                transformed_hall,
                transformed_hall.get_script_pointer(helper, 4),
            )
            self.assertEqual(helper_body, expected_north_helper_bodies[helper])

        self.assertEqual(transformed_hall.bytecode[0x4417:0x441C], b"\x14" * 5)
        self.assertNotIn(bytes.fromhex("F7 EE 82 00 80"), transformed_hall.bytecode)
        self.assertIn((376, 384), ROUTE_EDGES)
        self.assertIn((384, 376), ROUTE_EDGES)
        self.assertNotIn((384, 386), ROUTE_EDGES)
        self.assertNotIn((386, 384), ROUTE_EDGES)
        self.assertEqual(_clone(386).source_field, 374)

    def test_target_723_has_two_animated_reciprocal_route_doors(self) -> None:
        spec = _clone(723)
        donor, transformed = _donor_and_transformed(723)

        self.assertEqual((spec.source_field, spec.target_field), (375, 723))
        self.assertEqual(
            [
                (
                    edit.pc,
                    edit.old_field,
                    edit.old_parameter,
                    edit.new_field,
                    edit.new_parameter,
                )
                for edit in spec.transitions
            ],
            [
                (0x00D0, 372, 2, 371, 0),
                (0x0116, 376, 0, 726, 8),
                (0x017B, 376, 0, 726, 8),
            ],
        )
        self.assertEqual(
            [
                (
                    edit.entity,
                    edit.script_index,
                    edit.old_pointer,
                    edit.new_pointer,
                )
                for edit in spec.pointer_edits
            ],
            [(13, 2, 0x00F1, 0x0107)],
        )
        self.assertEqual(
            (
                donor.get_script_pointer(12, 2),
                transformed.get_script_pointer(12, 2),
            ),
            (0x00C1, 0x00C1),
        )
        self._assert_hardened_external_door(
            transformed,
            entity=12,
            action_pointer=0x00C1,
            collision_pointer=0x00D6,
            helpers=(15,),
            party_script=30,
            movement_x=-47,
            movement_z=-223,
            destination=371,
            parameter=0,
        )
        self.assertEqual(transformed.get_script_pointer(2, 30), 0x01C4)
        self.assertEqual(
            transformed.bytecode[0x00D0:0x00D5],
            _change_field(371, 0),
        )
        self.assertEqual(donor.get_script_pointer(13, 2), 0x00F1)
        self.assertEqual(transformed.get_script_pointer(13, 2), 0x0107)
        self._assert_hardened_external_door(
            transformed,
            entity=13,
            action_pointer=0x0107,
            collision_pointer=0x0181,
            helpers=(14,),
            party_script=31,
            movement_x=-47,
            movement_z=-223,
            destination=726,
            parameter=8,
            tail=bytes.fromhex("01 66 01"),
        )
        self.assertEqual(transformed.get_script_pointer(2, 31), 0x01D6)
        self.assertEqual(
            transformed.bytecode[0x0116:0x011B],
            _change_field(726, 8),
        )
        self.assertEqual(
            transformed.bytecode[0x0174:0x017B],
            bytes.fromhex("07 0E 24 26 54 80 0E"),
        )
        self.assertEqual(
            transformed.bytecode[0x017B:0x0180],
            _change_field(726, 8),
        )

