    def test_target_384_uses_one_no_escape_zeboim_guardian_in_factory_arena(
        self,
    ) -> None:
        project = REPOSITORY_ROOT
        input_root = project / "work"
        spec = _clone(384)
        encounter = spec.boss_encounter
        assert encounter is not None
        self.assertEqual(
            (
                encounter.donor_file,
                encounter.donor_formation,
                encounter.target_formation,
                encounter.no_escape,
                encounter.replacement_formation,
            ),
            (
                "reference_fields/field_403/06_encounters.bin",
                3,
                FIXED_BOSS_CONFIGURATION,
                True,
                ZEBOIM_GUARDIAN_FORMATION,
            ),
        )

        target_path = input_root / spec.bundle_directory / "06_encounters.bin"
        original = EncounterTable(target_path.read_bytes())
        donor = EncounterTable(
            (input_root / encounter.donor_file).read_bytes()
        )
        self.assertEqual(
            donor.formation(encounter.donor_formation),
            encounter.expected_formation,
        )
        self.assertEqual(original.get_weight(encounter.target_formation), 0)

        installed = EncounterTable(
            _install_boss_encounter(
                target_path.read_bytes(),
                input_root,
                encounter,
            )
        )
        formation = installed.formation(encounter.target_formation)
        self.assertEqual(formation, ZEBOIM_GUARDIAN_FORMATION)
        self.assertEqual(formation[0], 0x10)
        self.assertEqual(formation[1] & 0x80, 0x80)
        self.assertEqual(formation[2], 0x0B)
        self.assertEqual(installed.get_weight(encounter.target_formation), 0)
        self.assertEqual(
            installed.get_enemy_id(encounter.target_formation, 0),
            0,
        )
        self.assertTrue(
            installed.get_enemy(encounter.target_formation, 0).is_gear
        )
        self.assertEqual(
            installed.get_enemy_position(encounter.target_formation, 0),
            0,
        )
        for enemy_slot in range(1, 8):
            with self.subTest(enemy_slot=enemy_slot):
                self.assertEqual(
                    installed.get_enemy_id(
                        encounter.target_formation,
                        enemy_slot,
                    ),
                    0x7F,
                )

    def test_target_726_parameters_two_through_nine_relocate_early_scripts(
        self,
    ) -> None:
        spec = _clone(726)
        donor, transformed = _donor_and_transformed(726)

        self.assertEqual(
            spec.field_entry_additions,
            (
                FieldEntryAddition(43, 602, 0, 4, 4),
                FieldEntryAddition(20, -176, 0, 6, 6),
                FieldEntryAddition(-520, 485, 0, 2, 2),
                FieldEntryAddition(-529, -560, 0, 0, 0),
                FieldEntryAddition(-345, -545, 0, 6, 6),
                FieldEntryAddition(-529, 510, 0, 0, 0),
                FieldEntryAddition(88, -560, 0, 0, 0),
                FieldEntryAddition(20, 441, 0, 6, 6),
            ),
        )
        self.assertEqual(spec.field_entry_resume_pc, 0x0047)
        self.assertEqual(donor.bytecode_size, 0x01DC)
        self.assertEqual(
            donor.bytecode[0x000F:0x0017],
            bytes.fromhex("BC A0 00 80 23 80 90 81"),
        )
        self.assertEqual(
            transformed.bytecode[0x000F:0x0047],
            bytes.fromhex(
                "2B 00 5A 02 00 00 04 "
                "14 00 50 FF 00 06 06 "
                "F8 FD E5 01 00 02 02 "
                "EF FD D0 FD 00 00 00 "
                "A7 FE DF FD 00 06 06 "
                "EF FD FE 01 00 00 00 "
                "58 00 D0 FD 00 00 00 "
                "14 00 B9 01 00 06 06"
            ),
        )

        expected_pointers = {
            0: (0x032D, 0x034D, 0x034E, 0x034E),
            1: (0x034F, 0x0357, 0x0359, 0x0359),
            2: (0x035A, 0x0362, 0x0364, 0x0364),
            3: (0x0047, 0x004F, 0x0051, 0x0051),
        }
        for entity, expected in expected_pointers.items():
            with self.subTest(relocated_entity=entity):
                self.assertEqual(
                    tuple(
                        transformed.get_script_pointer(entity, script_index)
                        for script_index in range(4)
                    ),
                    expected,
                )

        trampoline = transformed.get_script_pointer(0, 0)
        self.assertEqual(
            transformed.bytecode[trampoline:0x034D],
            bytes.fromhex(
                "BC A0 00 80 23 80 90 81 "
                "2A FE 25 01 "
                "F7 84 83 01 80 "
                "86 A6 80 49 03 75 3A 80 "
                "01 4C 03 75 1A 80 00"
            ),
        )
        # The game-progress branch must land on the relocated alternate
        # music path, never inside parameter 6's entry record at PC 0x002B.
        self.assertEqual(
            struct.unpack_from("<H", transformed.bytecode, trampoline + 20)[0],
            0x0349,
        )
        self.assertEqual(
            transformed.bytecode[0x0349:0x034C],
            bytes.fromhex("75 1A 80"),
        )
        self.assertEqual(
            transformed.bytecode[0x034F:0x0357],
            donor.bytecode[0x0031:0x0039],
        )
        self.assertEqual(
            transformed.bytecode[0x035A:0x0362],
            donor.bytecode[0x003C:0x0044],
        )
        for entity in range(transformed.entity_count):
            for script_index in range(32):
                pointer = transformed.get_script_pointer(entity, script_index)
                with self.subTest(
                    preserved_pointer_entity=entity,
                    preserved_pointer_script=script_index,
                ):
                    self.assertFalse(0x000F <= pointer < 0x0047)

