        # The user's exact V151 F2 capture is immutable failure evidence. Its
        # hidden entity-13 owner reached dialogue 21 with flag zero, so
        # WAIT_DIALOG stopped the action at the native STOP while the box still
        # retained dialogue 21's pointer. Bit 12 therefore remained clear and
        # the camera stayed directly on Miang's hidden anchor. V152 repairs
        # those independent causes in generated source, without rewriting the
        # saved state.
        from tools.prepare_mass_driver_bootstrap import (
            BootstrapError,
            _Zstd,
            _frame_offsets,
        )
        from work.read_duckstation_runtime import RAM_SIZE, _psx_ram_offset

        project_root = REPOSITORY_ROOT
        failure_state = (
            project_root
            / "work"
            / "runtime_capture"
            / "v151_hidden_controller_dialogue_abort.sav"
        )
        failure_state_bytes = failure_state.read_bytes()
        self.assertEqual(
            (
                len(failure_state_bytes),
                hashlib.sha256(failure_state_bytes).hexdigest(),
            ),
            (
                1_752_967,
                "8bc81de760fda0ba5522c01b439a4aa152082bd8c48182e560c62f8747419717",
            ),
        )
        zstd = _Zstd(project_root / "work" / "duckstation" / "zstd.dll")
        failure_payload = None
        for frame_offset in reversed(_frame_offsets(failure_state_bytes)):
            try:
                failure_payload = zstd.decompress(
                    failure_state_bytes[frame_offset:]
                )
                break
            except BootstrapError:
                continue
        self.assertIsNotNone(failure_payload)
        assert failure_payload is not None
        ram_offset = _psx_ram_offset(failure_payload)
        failure_ram = failure_payload[ram_offset : ram_offset + RAM_SIZE]

        field_actors = struct.unpack_from("<I", failure_ram, 0x0AFB10)[0]
        field_actors &= 0x1FFFFFFF
        entity_13_actor = field_actors + 13 * 0x5C
        entity_13_data = struct.unpack_from(
            "<I", failure_ram, entity_13_actor + 0x4C
        )[0]
        entity_13_data &= 0x1FFFFFFF
        entity_13_dialogue_flags = struct.unpack_from(
            "<I", failure_ram, entity_13_data + 0x84
        )[0]
        entity_13_pc = struct.unpack_from(
            "<H", failure_ram, entity_13_data + 0xCC
        )[0]
        resident_bytecode = struct.unpack_from(
            "<I", failure_ram, 0x0ADC00
        )[0]
        resident_bytecode &= 0x1FFFFFFF
        self.assertEqual(
            (
                entity_13_dialogue_flags,
                entity_13_pc,
                failure_ram[resident_bytecode + entity_13_pc],
            ),
            (0, 0x0166, 0x00),
        )

