                (22, director_systems),
                (23, director_systems),
                (24, director_systems),
                (25, miang_director),
                (26, director_systems),
                (27, miang_director),
                (28, miang_director),
                (29, miang_director),
                (30, director_systems),
                (31, director_systems),
                (36, miang_director),
