        self.assertEqual(console.count(citan_prepare), 2)
        self.assertEqual(console.count(citan_load), 2)
        self.assertEqual(console.count(b"\xFE\x18"), 2)
        self.assertEqual(console.count(b"\xFE\x1A"), 2)
        self.assertEqual(console.count(citan_stage), 2)
        self.assertEqual(console.count(fresh_arrival_camera), 1)
        self.assertEqual(console.count(recovery_arrival_camera), 1)
        self.assertEqual(console.count(citan_suffix), 1)
        self.assertEqual(console.count(native_door_sound), 1)
        self.assertEqual(console.count(native_door_helper), 1)
        self.assertEqual(console.count(citan_walk), 1)
        self.assertEqual(console.count(arrival_write), 1)
        self.assertEqual(console.count(terminal_operation_camera), 1)
        self.assertEqual(console.count(terminal_operation_call), 1)
        self.assertEqual(console.count(terminal_operation_sequence), 1)
        self.assertEqual(console.count(citan_to_leader), 2)
