        self.assertLess(fresh_prepare_offset, fresh_camera_offset)
        self.assertLess(fresh_camera_offset, fresh_jump_offset)
        self.assertLess(fresh_jump_offset, recovery_prepare_offset)
        self.assertLess(recovery_prepare_offset, recovery_camera_offset)
        self.assertLess(recovery_camera_offset, shared_suffix_offset)
        self.assertLess(citan_show_offset, native_door_sound_offset)
        self.assertLess(native_door_sound_offset, native_door_helper_offset)
        self.assertLess(native_door_helper_offset, citan_walk_offset)
        self.assertLess(citan_walk_offset, suffix_facing_offset)
        self.assertLess(suffix_facing_offset, arrival_write_offset)
        self.assertLess(arrival_write_offset, commit_dialogue_offset)
